window.LAWS=window.LAWS||[];window.LAWS.push({"id": "L7", "ten": "Quy tắc ứng xử: Thông tư 03/2026/TT-BGDĐT (nhà giáo) và Thông tư 06/2019/TT-BGDĐT (cơ sở giáo dục)", "so": "TT 03/2026/TT-BGDĐT; TT 06/2019/TT-BGDĐT", "hieuluc": "30/01/2026 và 28/05/2019", "mota": "Quy tắc ứng xử của nhà giáo (TT 03/2026, thay QĐ 16/2008 và Điều 6 TT 06/2019) và Bộ quy tắc ứng xử trong cơ sở giáo dục mầm non, phổ thông, thường xuyên (TT 06/2019).", "baihoc": [{"id": "L7-1", "ten": "Thông tư 03/2026: phạm vi, mục đích, nguyên tắc và ứng xử chung (Điều 4)", "tomtat": ["TT 03/2026/TT-BGDĐT ban hành và có hiệu lực từ **30/01/2026**; gồm **03 chương, 15 điều**.", "Thay thế **Quyết định 16/2008/QĐ-BGDĐT** (đạo đức nhà giáo) và **Điều 6 Thông tư 06/2019/TT-BGDĐT** (chỉ Điều 6, không phải cả Thông tư 06).", "Áp dụng với **nhà giáo** làm nhiệm vụ giảng dạy, giáo dục trong cơ sở giáo dục thuộc hệ thống giáo dục quốc dân (kể cả nhà giáo lực lượng vũ trang, biệt phái); **không** áp dụng cho người học, cha mẹ, khách.", "Nội dung quy tắc nằm ở **Điều 4 đến Điều 9**, chia **6 nhóm**: chung (Đ4), người học (Đ5), đồng nghiệp (Đ6), cán bộ quản lý (Đ7), cha mẹ hoặc người giám hộ (Đ8), cộng đồng (Đ9).", "Mục đích: bảo đảm chuẩn mực nhận thức, thái độ, hành vi; môi trường giáo dục an toàn, thân thiện; phòng chống tiêu cực và bạo lực học đường; rèn luyện văn hóa ứng xử trong **môi trường số, đặc biệt trên mạng xã hội**.", "Nguyên tắc: tuân thủ pháp luật; bình đẳng, không phân biệt đối xử; tôn trọng đa dạng văn hóa, **đời sống riêng tư, bí mật cá nhân**; ngắn gọn, dễ hiểu; phù hợp cấp học, vùng miền; khả thi, dân chủ, công khai, khách quan.", "Điều 4 khoản 1: chấp hành chủ trương, đường lối của Đảng, chính sách, pháp luật; thực hiện đúng quyền, nghĩa vụ; chấp hành **phân công, điều động của người có thẩm quyền**.", "Điều 4 khoản 2: tận tụy; dạy đúng mục tiêu, nguyên lý giáo dục; trung thực trong học tập, NCKH, giảng dạy; tiếp thu **có chọn lọc** khoa học công nghệ; **có trách nhiệm khi sử dụng thông tin và ứng xử trên không gian mạng**.", "Điều 4 khoản 3: giữ gìn phẩm chất, uy tín, danh dự, nhân phẩm; mẫu mực, nêu gương; tiết kiệm, chống lãng phí, tham nhũng, **bệnh thành tích**; phê bình và tự phê bình thường xuyên.", "Điều 4 khoản 4: bảo vệ cảnh quan cơ sở giáo dục; phòng chống bạo lực học đường; đoàn kết, yêu thương, giúp đỡ; bảo vệ uy tín, danh dự người khác và của cơ sở giáo dục.", "Điều 4 khoản 5: ngôn ngữ trong sáng, dễ hiểu, đúng mực, trung thực, tôn trọng; trang phục gọn gàng, lịch sự, phù hợp môi trường và hoạt động giáo dục.", "Điều 4 khoản 6 (không được làm): lợi dụng chức danh, danh hiệu, hình ảnh nhà giáo để vi phạm pháp luật hay **tư lợi**; **tự ý bỏ việc**; tuyên truyền nội dung trái quan điểm, chính sách của Đảng và Nhà nước; không thờ ơ, né tránh hoặc **che giấu** vi phạm của người học, đồng nghiệp.", "Điều 4 khoản 6: không hút thuốc lá, sử dụng đồ uống có cồn **khi thực hiện nhiệm vụ**; không sử dụng chất cấm và chất kích thích khác theo quy định pháp luật; không tham gia tệ nạn xã hội."], "bay": ["⚠ TT03: hút thuốc, đồ uống có cồn bị cấm **'khi thực hiện nhiệm vụ'** ≠ TT06/2019: cấm **'trong cơ sở giáo dục'**.", "⚠ TT03 thay **Điều 6** của TT06/2019 (không phải cả TT06); và thay **QĐ 16/2008** (không phải QĐ khác).", "⚠ TT03 chỉ dành cho **nhà giáo**; TT06/2019 mới có quy tắc cho người học, cha mẹ, khách.", "⚠ Điều 4 khoản 6: 'né tránh' ≠ 'che giấu' ≠ 'thờ ơ' (đều bị cấm, nghe tương tự); nhớ đủ cụm 'không thờ ơ, né tránh hoặc che giấu'.", "⚠ Nội dung quy tắc là Điều **4–9** (6 nhóm), không phải Điều 1–6 hay 5–10."], "cauhoi": [{"t": "s", "q": "Thông tư 03/2026/TT-BGDĐT thay thế văn bản nào sau đây?", "o": ["Toàn bộ Thông tư 06/2019/TT-BGDĐT", "Quyết định 16/2008/QĐ-BGDĐT và Điều 6 Thông tư 06/2019/TT-BGDĐT", "Quyết định 16/2008/QĐ-BGDĐT và toàn bộ Thông tư 06/2019/TT-BGDĐT", "Chỉ Điều 6 Thông tư 06/2019/TT-BGDĐT, không thay thế Quyết định 16/2008/QĐ-BGDĐT"], "a": [1], "e": "TT03 thay QĐ 16/2008 (đạo đức nhà giáo) và chỉ Điều 6 của TT06/2019; các điều còn lại của TT06 không bị thay thế. Bẫy: 'toàn bộ' và 'chỉ Điều 6' đều sai.", "r": "Thông tư 03/2026/TT-BGDĐT (phần thay thế văn bản)"}, {"t": "s", "q": "Thông tư 03/2026/TT-BGDĐT gồm bao nhiêu chương, bao nhiêu điều?", "o": ["03 chương, 14 điều", "02 chương, 15 điều", "04 chương, 15 điều", "03 chương, 15 điều"], "a": [3], "e": "TT03 gồm 3 chương, 15 điều. Con số 14 điều là của TT06/2019 (cũng 3 chương, 14 điều).", "r": "Thông tư 03/2026/TT-BGDĐT"}, {"t": "s", "q": "Nội dung quy tắc ứng xử của nhà giáo theo Thông tư 03/2026/TT-BGDĐT được quy định tại các điều nào và gồm mấy nhóm?", "o": ["Điều 4 đến Điều 9; 6 nhóm", "Điều 1 đến Điều 6; 6 nhóm", "Điều 4 đến Điều 8; 5 nhóm", "Điều 5 đến Điều 10; 6 nhóm"], "a": [0], "e": "Điều 4 (chung), 5 (người học), 6 (đồng nghiệp), 7 (cán bộ quản lý), 8 (cha mẹ), 9 (cộng đồng) = 6 nhóm.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4–9"}, {"t": "s", "q": "Theo Thông tư 03/2026/TT-BGDĐT, nhà giáo không được hút thuốc lá, sử dụng đồ uống có cồn vào thời điểm nào?", "o": ["Trong cơ sở giáo dục", "Trong giờ lên lớp", "Khi thực hiện nhiệm vụ", "Ở mọi nơi, mọi lúc"], "a": [2], "e": "TT03 Điều 4 khoản 6: 'khi thực hiện nhiệm vụ'. Cụm 'trong cơ sở giáo dục' là của TT06/2019 Điều 4 khoản 6.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6"}, {"t": "s", "q": "Theo Điều 4 khoản 2 Thông tư 03/2026/TT-BGDĐT, nhà giáo phải có trách nhiệm khi sử dụng thông tin và ứng xử ở đâu?", "o": ["Trong lớp học", "Tại nơi công cộng", "Trên không gian mạng", "Trong gia đình"], "a": [2], "e": "Điều 4 khoản 2: có trách nhiệm khi sử dụng thông tin và ứng xử trên không gian mạng (nội dung về ứng xử mạng).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 2"}, {"t": "s", "q": "Phát biểu nào đúng về những điều nhà giáo không được làm theo Điều 4 khoản 6 Thông tư 03/2026/TT-BGDĐT?", "o": ["Không thờ ơ, né tránh hoặc che giấu hành vi vi phạm của người học, đồng nghiệp", "Được sử dụng đồ uống có cồn khi thực hiện nhiệm vụ nếu không say", "Chỉ cấm che giấu vi phạm của người học, còn vi phạm của đồng nghiệp thì không bắt buộc", "Được tuyên truyền nội dung trái chính sách của Nhà nước nếu là ý kiến cá nhân"], "a": [0], "e": "Điều 4 khoản 6 cấm cả thờ ơ/né tránh/che giấu vi phạm của người học lẫn đồng nghiệp; cấm đồ uống có cồn khi thực hiện nhiệm vụ (không phân biệt có say hay không); cấm tuyên truyền nội dung trái quan điểm, chính sách.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6"}, {"t": "s", "q": "Đối tượng điều chỉnh của Thông tư 03/2026/TT-BGDĐT là ai?", "o": ["Nhà giáo, người học và cha mẹ người học", "Chỉ nhà giáo trong cơ sở giáo dục công lập", "Cán bộ quản lý, giáo viên, nhân viên và khách đến cơ sở giáo dục", "Nhà giáo làm nhiệm vụ giảng dạy, giáo dục trong cơ sở giáo dục thuộc hệ thống giáo dục quốc dân"], "a": [3], "e": "TT03 chỉ quy định quy tắc ứng xử của nhà giáo. Việc quy định cả người học, cha mẹ, khách là của TT06/2019.", "r": "Thông tư 03/2026/TT-BGDĐT (phạm vi, đối tượng áp dụng)"}, {"t": "s", "q": "Theo Điều 4 khoản 5 Thông tư 03/2026/TT-BGDĐT, trang phục của nhà giáo phải như thế nào?", "o": ["Mặc đồng phục thống nhất của nhà trường", "Gọn gàng, lịch sự, phù hợp môi trường và hoạt động giáo dục", "Sạch sẽ, gọn gàng, phù hợp lứa tuổi", "Phù hợp tính chất công việc"], "a": [1], "e": "TT03 khoản 5: gọn gàng, lịch sự, phù hợp môi trường và hoạt động giáo dục. 'Sạch sẽ, gọn gàng' là yêu cầu với người học; 'phù hợp tính chất công việc' là với nhân viên (TT06 Điều 4 khoản 4).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 5"}, {"t": "s", "q": "Theo Điều 4 khoản 3 Thông tư 03/2026/TT-BGDĐT, nhà giáo tiết kiệm, chống những gì?", "o": ["Lãng phí, tham nhũng, bệnh thành tích", "Lãng phí, tham nhũng, tiêu cực trong thi cử", "Lãng phí, bệnh thành tích, bạo lực học đường", "Tham nhũng, bệnh thành tích, tin giả"], "a": [0], "e": "Khoản 3: tiết kiệm, chống lãng phí, tham nhũng, bệnh thành tích. Các cụm khác (tiêu cực thi cử, bạo lực học đường, tin giả) nằm ở các nội dung khác nên không đúng cụm này.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 3"}, {"t": "s", "q": "Thông tư 03/2026/TT-BGDĐT làm căn cứ để nhà giáo rèn luyện văn hóa ứng xử trong môi trường nào được nhấn mạnh?", "o": ["Môi trường lớp học, đặc biệt trong giờ dạy", "Môi trường gia đình, đặc biệt với cha mẹ người học", "Môi trường số, đặc biệt trên mạng xã hội", "Môi trường quốc tế, đặc biệt trong hợp tác giáo dục"], "a": [2], "e": "Mục đích của TT03 nêu rõ văn hóa ứng xử trong môi trường số, đặc biệt trên mạng xã hội.", "r": "Thông tư 03/2026/TT-BGDĐT (mục đích)"}, {"t": "s", "q": "Nguyên tắc nào sau đây đúng với việc xây dựng quy tắc ứng xử của nhà giáo theo Thông tư 03/2026/TT-BGDĐT?", "o": ["Áp dụng thống nhất tuyệt đối, không tính đến cấp học và vùng miền", "Phù hợp cấp học, trình độ đào tạo, phương thức giáo dục, đặc trưng vùng miền", "Ưu tiên bảo vệ uy tín nhà trường hơn quyền riêng tư của cá nhân", "Chỉ cần khả thi, không cần công khai"], "a": [1], "e": "Nguyên tắc: phù hợp cấp học, trình độ đào tạo, phương thức, vùng miền; tôn trọng đời sống riêng tư, bí mật cá nhân; khả thi, dân chủ, công khai, khách quan.", "r": "Thông tư 03/2026/TT-BGDĐT (nguyên tắc)"}, {"t": "s", "q": "Điều 4 khoản 1 Thông tư 03/2026/TT-BGDĐT yêu cầu nhà giáo chấp hành sự phân công, điều động của ai?", "o": ["Hiệu trưởng", "Tổ trưởng chuyên môn", "Cơ quan quản lý giáo dục cấp trên", "Người có thẩm quyền"], "a": [3], "e": "Khoản 1: 'người có thẩm quyền' (không giới hạn một chức danh cụ thể như hiệu trưởng).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 1"}, {"t": "m", "q": "Những hành vi nào sau đây nhà giáo không được làm theo Điều 4 khoản 6 Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Sử dụng đồ uống có cồn khi thực hiện nhiệm vụ", "Tham gia hoạt động từ thiện, nhân đạo", "Che giấu hành vi vi phạm của đồng nghiệp", "Tự phê bình và phê bình thường xuyên", "Tự ý bỏ việc"], "a": [0, 2, 4], "e": "Tự ý bỏ việc, uống rượu bia khi thực hiện nhiệm vụ, che giấu vi phạm đều bị cấm. Từ thiện (Điều 9) và phê bình, tự phê bình (Điều 4 khoản 3) là việc nên làm.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6"}, {"t": "m", "q": "Các nhóm quan hệ nào là đối tượng ứng xử của nhà giáo được quy định riêng trong Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Khách đến cơ sở giáo dục", "Nhân viên cơ sở giáo dục", "Cha mẹ hoặc người giám hộ của người học", "Người học", "Cộng đồng"], "a": [2, 3, 4], "e": "TT03 có 6 nhóm: chung, người học, đồng nghiệp, cán bộ quản lý, cha mẹ/người giám hộ, cộng đồng. 'Khách' và 'nhân viên' là nhóm trong TT06/2019.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4–9"}, {"t": "m", "q": "Mục đích của Thông tư 03/2026/TT-BGDĐT gồm những nội dung nào? (chọn tất cả đáp án đúng)", "o": ["Bảo đảm chuẩn mực nhận thức, thái độ, hành vi của nhà giáo", "Thay thế toàn bộ Luật Nhà giáo 2025", "Phòng chống tiêu cực và bạo lực học đường", "Tạo cơ sở pháp lý thống nhất để cơ sở giáo dục xây dựng quy tắc phù hợp thực tiễn", "Quy định cách ứng xử của người học và cha mẹ người học"], "a": [0, 2, 3], "e": "TT03 chỉ điều chỉnh ứng xử của nhà giáo, không quy định cho người học, cha mẹ (là TT06/2019) và không thay Luật.", "r": "Thông tư 03/2026/TT-BGDĐT (mục đích)"}, {"t": "m", "q": "Điều 4 khoản 2 Thông tư 03/2026/TT-BGDĐT yêu cầu nhà giáo thực hiện những nội dung nào? (chọn tất cả đáp án đúng)", "o": ["Tiếp thu toàn bộ khoa học công nghệ mới", "Dạy đúng mục tiêu, nguyên lý giáo dục", "Thực hiện chương trình ở mức tối thiểu", "Trung thực trong học tập, nghiên cứu khoa học, giảng dạy", "Tiếp thu có chọn lọc khoa học và công nghệ"], "a": [1, 3, 4], "e": "Khoản 2 nêu 'tiếp thu có chọn lọc' và 'thực hiện đầy đủ, bảo đảm chất lượng chương trình'. 'Toàn bộ' và 'tối thiểu' là bẫy.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 2"}, {"t": "m", "q": "Điều 4 khoản 4 Thông tư 03/2026/TT-BGDĐT quy định nhà giáo thực hiện những việc nào? (chọn tất cả đáp án đúng)", "o": ["Chỉ bảo vệ uy tín, danh dự của bản thân", "Bảo vệ cảnh quan cơ sở giáo dục", "Phòng chống bạo lực học đường", "Xây dựng quy tắc ứng xử cho cha mẹ người học", "Bảo vệ uy tín, danh dự của người khác và của cơ sở giáo dục"], "a": [1, 2, 4], "e": "Khoản 4 yêu cầu bảo vệ uy tín, danh dự của người khác và cơ sở giáo dục (không chỉ bản thân).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 4"}, {"t": "f", "q": "Thông tư 03/2026/TT-BGDĐT có hiệu lực thi hành từ ngày ____.", "a": [["30/01/2026", "30/1/2026"]], "e": "TT03 ban hành và có hiệu lực từ 30/01/2026.", "r": "Thông tư 03/2026/TT-BGDĐT", "o": [["01/01/2026"], ["30/01/2026"], ["30/01/2025"], ["15/03/2026"]], "k": 1}, {"t": "f", "q": "Thông tư 03/2026/TT-BGDĐT gồm ____ chương và ____ điều.", "a": [["3", "03", "ba"], ["15", "mười lăm"]], "e": "3 chương, 15 điều (TT06/2019 là 3 chương, 14 điều).", "r": "Thông tư 03/2026/TT-BGDĐT", "o": [["3", "14"], ["4", "15"], ["2", "16"], ["3", "15"]], "k": 3}, {"t": "f", "q": "Nhà giáo không hút thuốc lá, sử dụng đồ uống có cồn khi ____.", "a": [["thực hiện nhiệm vụ"]], "e": "TT03: 'khi thực hiện nhiệm vụ'; TT06: 'trong cơ sở giáo dục'.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6", "o": [["trong cơ sở giáo dục"], ["thực hiện nhiệm vụ"], ["ngoài giờ làm việc"], ["trong giờ lên lớp"]], "k": 1}, {"t": "f", "q": "Nhà giáo không thờ ơ, né tránh hoặc ____ hành vi vi phạm của người học, đồng nghiệp.", "a": [["che giấu"]], "e": "Cụm đúng: 'không thờ ơ, né tránh hoặc che giấu'.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6", "o": [["phê phán"], ["tố cáo"], ["báo cáo"], ["che giấu"]], "k": 3}, {"t": "f", "q": "Nhà giáo không lợi dụng chức danh, danh hiệu, hình ảnh nhà giáo và hoạt động nghề nghiệp để vi phạm pháp luật hay ____ cá nhân.", "a": [["tư lợi"]], "e": "Điều 4 khoản 6: vi phạm pháp luật hay tư lợi cá nhân.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6", "o": [["phục vụ"], ["bảo vệ"], ["tư lợi"], ["hỗ trợ"]], "k": 2}, {"t": "f", "q": "Nhà giáo tiết kiệm, chống lãng phí, tham nhũng, bệnh ____.", "a": [["thành tích"]], "e": "Điều 4 khoản 3.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 3", "o": [["hình thức"], ["quan liêu"], ["thành tích"], ["bảo thủ"]], "k": 2}, {"t": "f", "q": "Nhà giáo có trách nhiệm khi sử dụng thông tin và ứng xử trên ____.", "a": [["không gian mạng"]], "e": "Điều 4 khoản 2.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 2", "o": [["không gian mạng"], ["mạng xã hội"], ["internet"], ["truyền thông đại chúng"]], "k": 0}, {"t": "f", "q": "Nội dung quy tắc ứng xử của nhà giáo nằm từ Điều ____ đến Điều ____ của Thông tư 03/2026/TT-BGDĐT.", "a": [["4", "bốn"], ["9", "chín"]], "e": "6 nhóm ứng xử từ Điều 4 đến Điều 9.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4–9", "o": [["3", "9"], ["4", "10"], ["4", "9"], ["5", "8"]], "k": 2}, {"t": "f", "q": "Thông tư 03/2026/TT-BGDĐT thay thế Quyết định số ____/2008/QĐ-BGDĐT về đạo đức nhà giáo.", "a": [["16"]], "e": "QĐ 16/2008/QĐ-BGDĐT ngày 16/4/2008.", "r": "Thông tư 03/2026/TT-BGDĐT (phần thay thế văn bản)", "o": [["06"], ["16"], ["20"], ["15"]], "k": 1}], "ynho": ["TT **03/2026** có hiệu lực **30/01/2026**; gồm **3 chương, 15 điều**.", "Thay **QĐ 16/2008** và chỉ **Điều 6** của TT 06/2019.", "Quy tắc nằm ở **Điều 4–9**, chia **6 nhóm** quan hệ.", "Cấm hút thuốc, đồ uống có cồn **khi thực hiện nhiệm vụ**.", "Không **thờ ơ, né tránh hoặc che giấu** vi phạm của người học, đồng nghiệp."], "bang": [{"tieu_de": "6 nhóm ứng xử của TT03/2026 (Điều 4–9)", "cot": ["Điều", "Nhóm quan hệ", "Từ khoá"], "dong": [["4", "Ứng xử chung", "Không gian mạng, tư lợi, bỏ việc, thờ ơ-né tránh-che giấu"], ["5", "Người học", "Không phân biệt đối xử, phải báo cáo bạo lực"], ["6", "Đồng nghiệp", "Không chia rẽ, đùn đẩy, công khai thông tin"], ["7", "Cán bộ quản lý", "Chấp hành, cầu thị, tham mưu, chính kiến"], ["8", "Cha mẹ/người giám hộ", "Thông tin trung thực, không ép buộc"], ["9", "Cộng đồng", "Chống tin giả, không mê tín dị đoan"]]}, {"tieu_de": "TT03/2026 và TT06/2019 dễ nhầm", "cot": ["Tiêu chí", "TT03/2026", "TT06/2019"], "dong": [["Hiệu lực", "30/01/2026", "28/5/2019"], ["Quy mô", "3 chương, 15 điều", "3 chương, 14 điều"], ["Đối tượng", "Chỉ nhà giáo", "CBQL, GV, nhân viên, người học, cha mẹ, khách"], ["Cấm thuốc lá, cồn", "Khi thực hiện nhiệm vụ", "Trong cơ sở giáo dục"], ["Quan hệ", "Thay QĐ 16/2008 và Điều 6 TT06", "Điều 6 hết hiệu lực từ 30/01/2026"]]}], "vidu": [{"tinh_huong": "Thầy Nam, giáo viên Tin học, đang trực ban sân trường giờ ra chơi thì ra góc sân hút thuốc lá.", "ket_luan": "→ Vi phạm. Điều 4 khoản 6 TT03/2026 cấm hút thuốc lá khi thực hiện nhiệm vụ."}, {"tinh_huong": "Tối thứ Bảy, cô Hà chia sẻ lên Facebook một bài 'tin nóng' về chính sách giáo dục mà chưa kiểm chứng nguồn, nhiều đồng nghiệp share lại.", "ket_luan": "→ Không phù hợp. Điều 4 khoản 2 yêu cầu có trách nhiệm khi sử dụng thông tin và ứng xử trên không gian mạng."}, {"tinh_huong": "Cô Lan chứng kiến một đồng nghiệp quát tháo, đánh học sinh ở hành lang nhưng im lặng 'cho khỏi mất lòng'.", "ket_luan": "→ Vi phạm. Điều 4 khoản 6 cấm thờ ơ, né tránh hoặc che giấu vi phạm của người học, đồng nghiệp."}, {"tinh_huong": "Cô Mai tự giới thiệu 'cô giáo trường X' trong nhóm Zalo phụ huynh để bán thực phẩm chức năng cho phụ huynh.", "ket_luan": "→ Vi phạm. Điều 4 khoản 6 cấm lợi dụng chức danh, hình ảnh nhà giáo để tư lợi."}, {"tinh_huong": "Thầy Bình nhận quyết định điều động sang cơ sở khác nhưng không đồng ý, không bàn giao mà nghỉ làm luôn.", "ket_luan": "→ Vi phạm. Điều 4 khoản 1 yêu cầu chấp hành điều động của người có thẩm quyền; khoản 6 cấm tự ý bỏ việc."}], "nho": ["Điều 4–9 = 6 nhóm: Chung – Học trò – Đồng nghiệp – Sếp (CBQL) – Phụ huynh – Cộng đồng, đúng thứ tự 4-5-6-7-8-9.", "TT**03** = '**t**hực hiện nhiệm vụ' (không ở nhà thì không cấm); TT**06** = '**t**rong cơ sở giáo dục' (cứ ở trường là cấm).", "Ba chữ 'thờ ơ – né tránh – che giấu' luôn đi cùng nhau, nhớ đủ cả cụm.", "Thay thế: 'QĐ 16/2008 + Điều 6 TT06' (chỉ một điều, không phải cả TT06)."]}, {"id": "L7-2", "ten": "Thông tư 03/2026: ứng xử của nhà giáo với người học (Điều 5)", "tomtat": ["Điều 5 khoản 1: thái độ mẫu mực, bao dung, trách nhiệm, yêu thương; phản hồi, nhận xét, **khen hoặc phê bình phù hợp đối tượng và hoàn cảnh**; động viên, khích lệ.", "Điều 5 khoản 2: tạo môi trường giáo dục **an toàn, tích cực, bình đẳng**; khuyến khích người học nghiên cứu, lao động sản xuất, hoạt động phục vụ cộng đồng, phát triển bền vững.", "Điều 5 khoản 3: tôn trọng, đánh giá **đúng thực chất** năng lực; bảo vệ quyền, lợi ích hợp pháp, chính đáng của người học; tạo động lực.", "Điều 5 khoản 3: lắng nghe, **kịp thời** tư vấn, hỗ trợ về học tập, xã hội, phù hợp **tâm sinh lý lứa tuổi**.", "Điều 5 khoản 4 (không được làm) - **không phân biệt đối xử** giữa người học dưới mọi hình thức.", "Điều 5 khoản 4: không **xúc phạm, gây tổn thương, trù dập, định kiến, bạo hành, xâm hại** người học dưới mọi hình thức.", "Điều 5 khoản 4: khi phát hiện người học bị bạo lực, xâm hại thì **phải báo cáo kịp thời** với lãnh đạo, cơ quan có thẩm quyền.", "Điều 5 khoản 4: không **ép buộc** người học tham gia hoạt động mang tính chất **tự nguyện**.", "Điều 5 khoản 4: không **công khai thông tin của người học trái quy định**.", "Điều 5 khoản 4: không **gian lận, cố ý làm sai lệch kết quả** trong tuyển sinh, đánh giá người học.", "Liên hệ: Điều 4 khoản 6 cấm thờ ơ, né tránh, che giấu vi phạm; Điều 4 khoản 5 yêu cầu ngôn ngữ đúng mực."], "bay": ["⚠ Điều 5 khoản 4: 'ép buộc người học tham gia hoạt động **tự nguyện**' ≠ Điều 8 khoản 4: 'ép buộc **cha mẹ** tham gia hoạt động trái quy định của Nhà nước và hoạt động tự nguyện'.", "⚠ 'Đánh giá **đúng thực chất**' ≠ đánh giá theo hướng nâng điểm để khích lệ; 'gian lận, cố ý làm **sai lệch** kết quả'.", "⚠ Khi phát hiện bạo lực, xâm hại thì **phải** báo cáo kịp thời (không phải 'có thể'); báo cáo lãnh đạo, cơ quan có thẩm quyền.", "⚠ 'Phân biệt đối xử' và 'xúc phạm, trù dập...' đều áp dụng 'dưới mọi hình thức' (không có ngoại lệ)."], "cauhoi": [{"t": "s", "q": "Theo Điều 5 khoản 1 Thông tư 03/2026/TT-BGDĐT, khi phản hồi, nhận xét, khen hoặc phê bình người học, nhà giáo phải làm thế nào?", "o": ["Phê bình công khai trước lớp để làm gương cho người khác", "Phù hợp đối tượng và hoàn cảnh", "Chỉ khen, không phê bình để tránh tổn thương", "Áp dụng cùng một mức độ cho mọi người học"], "a": [1], "e": "Điều 5 khoản 1: khen hoặc phê bình phù hợp đối tượng và hoàn cảnh; không có chuyện một mức cho mọi người học hay chỉ khen không phê bình.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 1"}, {"t": "s", "q": "Điều 5 khoản 3 Thông tư 03/2026/TT-BGDĐT yêu cầu nhà giáo đánh giá năng lực người học như thế nào?", "o": ["Theo hướng nâng điểm để tạo động lực", "Theo mặt bằng chung của lớp", "Ưu tiên người học có hoàn cảnh khó khăn", "Đúng thực chất"], "a": [3], "e": "Khoản 3: tôn trọng, đánh giá đúng thực chất năng lực. Nâng điểm là làm sai lệch, vi phạm khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 3"}, {"t": "s", "q": "Khi phát hiện người học bị bạo lực, xâm hại, nhà giáo phải làm gì theo Điều 5 khoản 4 Thông tư 03/2026/TT-BGDĐT?", "o": ["Báo cáo kịp thời với lãnh đạo, cơ quan có thẩm quyền", "Tự giải quyết nội bộ, không cần báo cáo", "Chỉ báo cáo khi cha mẹ người học yêu cầu", "Báo cáo vào cuối năm học"], "a": [0], "e": "Khoản 4: phải báo cáo kịp thời với lãnh đạo, cơ quan có thẩm quyền; Điều 4 khoản 6 cấm thờ ơ, né tránh, che giấu.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4"}, {"t": "s", "q": "Cô giáo bắt buộc cả lớp phải tham gia câu lạc bộ ngoại khóa mang tính tự nguyện, em nào không tham gia sẽ bị hạ hạnh kiểm. Hành vi này vi phạm quy định nào?", "o": ["Không vi phạm vì nhằm mục đích giáo dục", "Điều 8 khoản 4: không ép buộc cha mẹ tham gia hoạt động", "Điều 5 khoản 4: không ép buộc người học tham gia hoạt động mang tính chất tự nguyện", "Điều 6 khoản 3: không đùn đẩy trách nhiệm với đồng nghiệp"], "a": [2], "e": "Đối tượng bị ép buộc là người học nên áp dụng Điều 5 khoản 4. Điều 8 khoản 4 áp dụng khi ép buộc cha mẹ người học.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4"}, {"t": "s", "q": "Một giáo viên đăng ảnh bài kiểm tra điểm kém của một học sinh lên nhóm phụ huynh của lớp. Hành vi này vi phạm quy định nào của Thông tư 03/2026/TT-BGDĐT?", "o": ["Không vi phạm vì nhóm phụ huynh là kênh chính thống", "Không tham gia tệ nạn xã hội (Điều 4 khoản 6)", "Không công khai thông tin của người học trái quy định (Điều 5 khoản 4)", "Không tự ý bỏ việc (Điều 4 khoản 6)"], "a": [2], "e": "Công khai thông tin của người học trái quy định là hành vi bị cấm ở Điều 5 khoản 4; phụ huynh khác không phải đối tượng được chia sẻ thông tin đó.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4"}, {"t": "s", "q": "Quy định về gian lận, cố ý làm sai lệch kết quả trong tuyển sinh, đánh giá người học nằm ở điều khoản nào của Thông tư 03/2026/TT-BGDĐT?", "o": ["Điều 5 khoản 4", "Điều 6 khoản 3", "Điều 7 khoản 4", "Điều 8 khoản 4"], "a": [0], "e": "Điều 5 khoản 4 (ứng xử với người học) có điểm cấm gian lận, làm sai lệch kết quả tuyển sinh, đánh giá. Điều 6 K3, 7 K4, 8 K4 là các điều cấm với đồng nghiệp, cán bộ quản lý, cha mẹ.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4"}, {"t": "s", "q": "Theo Điều 5 khoản 2 Thông tư 03/2026/TT-BGDĐT, nhà giáo tạo môi trường giáo dục như thế nào?", "o": ["An toàn, cạnh tranh, kỷ luật", "Thân thiện, tiết kiệm, kỷ luật", "Bình đẳng, nghiêm khắc, cạnh tranh", "An toàn, tích cực, bình đẳng"], "a": [3], "e": "Khoản 2: môi trường giáo dục an toàn, tích cực, bình đẳng.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 2"}, {"t": "s", "q": "Điều 5 khoản 3 Thông tư 03/2026/TT-BGDĐT yêu cầu tư vấn, hỗ trợ người học phải phù hợp với yếu tố nào?", "o": ["Kết quả học tập của người học", "Tâm sinh lý lứa tuổi", "Điều kiện kinh tế gia đình", "Nguyện vọng của cha mẹ"], "a": [1], "e": "Khoản 3: lắng nghe, kịp thời tư vấn, hỗ trợ về học tập, xã hội, phù hợp tâm sinh lý lứa tuổi.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 3"}, {"t": "s", "q": "Phát biểu nào đúng về hành vi bị cấm đối với người học theo Điều 5 khoản 4 Thông tư 03/2026/TT-BGDĐT?", "o": ["Không phân biệt đối xử giữa người học dưới mọi hình thức", "Không phân biệt đối xử giữa người học, trừ trường hợp học lực yếu", "Chỉ cấm bạo hành về thân thể, không cấm xúc phạm bằng lời nói", "Chỉ cấm xâm hại, không cấm trù dập"], "a": [0], "e": "Khoản 4: cấm phân biệt đối xử, xúc phạm, gây tổn thương, trù dập, định kiến, bạo hành, xâm hại 'dưới mọi hình thức', không có ngoại lệ.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4"}, {"t": "s", "q": "Giáo viên nói 'ngu như bò' với học sinh trước lớp. Hành vi này vi phạm quy định nào của Thông tư 03/2026/TT-BGDĐT?", "o": ["Không vi phạm vì chỉ là lời nói, không bạo hành thể chất", "Chỉ vi phạm khi học sinh hoặc cha mẹ phản ánh", "Không xúc phạm, gây tổn thương người học dưới mọi hình thức (Điều 5 khoản 4)", "Điều 6 khoản 3: không xúc phạm đồng nghiệp"], "a": [2], "e": "Xúc phạm, gây tổn thương người học 'dưới mọi hình thức' (kể cả lời nói) bị cấm; Điều 4 khoản 5 cũng yêu cầu ngôn ngữ đúng mực.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4; Điều 4 khoản 5"}, {"t": "s", "q": "Phát biểu nào đúng khi so sánh quy định ép buộc trong Điều 5 và Điều 8 của Thông tư 03/2026/TT-BGDĐT?", "o": ["Điều 5 cấm ép buộc người học tham gia hoạt động trái quy định của Nhà nước; Điều 8 cấm ép buộc cha mẹ tham gia hoạt động tự nguyện", "Điều 5 cấm ép buộc người học tham gia hoạt động mang tính chất tự nguyện; Điều 8 cấm ép buộc cha mẹ tham gia hoạt động trái quy định của Nhà nước và hoạt động mang tính chất tự nguyện", "Cả hai điều đều chỉ cấm ép buộc người học", "Điều 8 chỉ cấm ép buộc cha mẹ tham gia hoạt động trái quy định, không nhắc đến hoạt động tự nguyện"], "a": [1], "e": "Điều 5 K4: người học + hoạt động tự nguyện. Điều 8 K4: cha mẹ + hoạt động trái quy định của Nhà nước và hoạt động tự nguyện. Các phương án nhiễu đảo chủ thể hoặc bỏ bớt vế.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4; Điều 8 khoản 4"}, {"t": "s", "q": "Điều 5 khoản 2 Thông tư 03/2026/TT-BGDĐT khuyến khích người học hoạt động nào sau đây?", "o": ["Thi đua tích lũy điểm số, giành giải thưởng", "Chỉ tham gia hoạt động học thuật", "Tham gia hoạt động từ thiện bắt buộc theo kế hoạch", "Nghiên cứu, lao động sản xuất, hoạt động phục vụ cộng đồng, phát triển bền vững"], "a": [3], "e": "Khoản 2 khuyến khích (không bắt buộc) nghiên cứu, lao động sản xuất, hoạt động phục vụ cộng đồng, phát triển bền vững.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 2"}, {"t": "m", "q": "Những hành vi nào nhà giáo không được làm với người học theo Điều 5 khoản 4 Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Định kiến với người học", "Động viên, khích lệ người học", "Tư vấn, hỗ trợ người học về học tập", "Phân biệt đối xử giữa người học", "Cố ý làm sai lệch kết quả đánh giá người học"], "a": [0, 3, 4], "e": "Phân biệt đối xử, định kiến, làm sai lệch kết quả đánh giá đều bị cấm. Động viên, tư vấn là việc nhà giáo cần làm.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5"}, {"t": "m", "q": "Giáo viên phát hiện một học sinh bị bạo lực. Hành động nào phù hợp với Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Báo cáo kịp thời với lãnh đạo, cơ quan có thẩm quyền", "Không thờ ơ, né tránh hoặc che giấu", "Bảo vệ quyền, lợi ích hợp pháp, chính đáng của học sinh", "Tự xử lý riêng để giữ uy tín nhà trường", "Chờ cha mẹ đồng ý rồi mới báo cáo"], "a": [0, 1, 2], "e": "Phải báo cáo kịp thời (Điều 5 K4), không che giấu (Điều 4 K6) và bảo vệ quyền lợi của học sinh (Điều 5 K3). 'Chờ đồng ý' hoặc 'giữ uy tín' là che giấu.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 3, 4; Điều 4 khoản 6"}, {"t": "m", "q": "Điều 5 khoản 3 Thông tư 03/2026/TT-BGDĐT yêu cầu nhà giáo thực hiện những việc nào? (chọn tất cả đáp án đúng)", "o": ["Nâng điểm để người học có động lực", "Bảo vệ quyền, lợi ích hợp pháp, chính đáng của người học", "Đánh giá theo thứ hạng so sánh giữa người học", "Tôn trọng, đánh giá đúng thực chất năng lực người học", "Lắng nghe, kịp thời tư vấn, hỗ trợ người học"], "a": [1, 3, 4], "e": "Khoản 3 yêu cầu đánh giá đúng thực chất, không nâng điểm. (Không so sánh học sinh với nhau là nội dung của Điều lệ trường phổ thông, không thuộc khoản này.)", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 3"}, {"t": "m", "q": "Hành vi nào sau đây vi phạm Điều 5 khoản 4 Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Khen ngợi học sinh có tiến bộ", "Sửa điểm bài kiểm tra cho học sinh", "Nhắc nhở riêng một học sinh vi phạm nội quy, phù hợp hoàn cảnh", "Bắt học sinh tham gia hoạt động tự nguyện, không tham gia thì hạ hạnh kiểm", "Đăng công khai điểm kém của một học sinh lên nhóm phụ huynh trái quy định"], "a": [1, 3, 4], "e": "Ba hành vi đầu lần lượt là công khai thông tin trái quy định, làm sai lệch kết quả, ép buộc hoạt động tự nguyện; hai hành vi còn lại là ứng xử đúng (Điều 5 khoản 1).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4"}, {"t": "f", "q": "Nhà giáo không ____ đối xử giữa người học dưới mọi hình thức.", "a": [["phân biệt"]], "e": "Điều 5 khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4", "o": [["phân loại"], ["so sánh"], ["phân biệt"], ["chênh lệch"]], "k": 2}, {"t": "f", "q": "Nhà giáo không ép buộc người học tham gia hoạt động mang tính chất ____.", "a": [["tự nguyện"]], "e": "Điều 5 khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4", "o": [["bắt buộc"], ["hành chính"], ["tự nguyện"], ["từ thiện"]], "k": 2}, {"t": "f", "q": "Nhà giáo không công khai thông tin của người học ____ quy định.", "a": [["trái"]], "e": "Điều 5 khoản 4: 'trái quy định'.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4", "o": [["ngoài"], ["vượt"], ["đúng"], ["trái"]], "k": 3}, {"t": "f", "q": "Khi phát hiện người học bị bạo lực, xâm hại, nhà giáo phải ____ kịp thời với lãnh đạo, cơ quan có thẩm quyền.", "a": [["báo cáo"]], "e": "Điều 5 khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4", "o": [["báo cáo"], ["xử lý"], ["hòa giải"], ["giữ bí mật"]], "k": 0}, {"t": "f", "q": "Nhà giáo tôn trọng, đánh giá ____ năng lực người học.", "a": [["đúng thực chất"]], "e": "Điều 5 khoản 3.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 3", "o": [["thấp hơn"], ["phóng đại"], ["đúng thực chất"], ["một chiều"]], "k": 2}, {"t": "f", "q": "Nhà giáo không xúc phạm, gây tổn thương, ____, định kiến, bạo hành, xâm hại người học dưới mọi hình thức.", "a": [["trù dập"]], "e": "Điều 5 khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4", "o": [["ưu ái"], ["dung túng"], ["lạm dụng"], ["trù dập"]], "k": 3}, {"t": "f", "q": "Nhà giáo không gian lận, cố ý làm ____ kết quả trong tuyển sinh, đánh giá người học.", "a": [["sai lệch"]], "e": "Điều 5 khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5 khoản 4", "o": [["chậm trễ"], ["sai lệch"], ["thất lạc"], ["giảm"]], "k": 1}, {"t": "f", "q": "Ứng xử của nhà giáo với người học được quy định tại Điều ____ Thông tư 03/2026/TT-BGDĐT.", "a": [["5", "năm"]], "e": "Điều 5.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 5", "o": [["4"], ["6"], ["5"], ["7"]], "k": 2}], "ynho": ["Điều 5 khoản 4 là nhóm điều **không được làm** với người học.", "**Không phân biệt đối xử** giữa người học dưới mọi hình thức.", "Phát hiện người học bị bạo lực, xâm hại thì **phải báo cáo kịp thời**.", "Không **ép buộc** người học tham gia hoạt động **tự nguyện**; không **công khai thông tin** trái quy định.", "Đánh giá **đúng thực chất**; không **gian lận, cố ý làm sai lệch** kết quả."], "bang": [{"tieu_de": "Điều 5 theo từng khoản", "cot": ["Khoản", "Nội dung", "Từ khoá"], "dong": [["1", "Thái độ, phản hồi, khen hoặc phê bình", "Phù hợp đối tượng và hoàn cảnh"], ["2", "Tạo môi trường giáo dục", "An toàn, tích cực, bình đẳng"], ["3", "Đánh giá và hỗ trợ người học", "Đúng thực chất; tư vấn kịp thời; tâm sinh lý lứa tuổi"], ["4", "Những điều không được làm", "5 nhóm hành vi cấm (xem bảng dưới)"]]}, {"tieu_de": "Điều 5 khoản 4: không được làm", "cot": ["Hành vi cấm", "Từ khoá"], "dong": [["Phân biệt đối xử", "Dưới mọi hình thức"], ["Xúc phạm, gây tổn thương, trù dập, định kiến, bạo hành, xâm hại", "Dưới mọi hình thức; phát hiện thì phải báo cáo"], ["Ép buộc tham gia hoạt động tự nguyện", "Hoạt động mang tính chất tự nguyện"], ["Công khai thông tin người học", "Trái quy định"], ["Gian lận, cố ý làm sai lệch kết quả", "Tuyển sinh, đánh giá người học"]]}], "vidu": [{"tinh_huong": "Trong giờ, cô Thu nói trước cả lớp: 'Lớp này có Long là hết thuốc chữa', khiến em Long cúi mặt khóc.", "ket_luan": "→ Vi phạm. Điều 5 khoản 4 cấm xúc phạm, gây tổn thương người học; khoản 1 yêu cầu phê bình phù hợp đối tượng và hoàn cảnh."}, {"tinh_huong": "Thầy Hưng chụp bảng điểm có tên và thứ hạng từng em đăng vào nhóm Zalo chung của phụ huynh mà không có quy định cho phép.", "ket_luan": "→ Vi phạm. Đó là công khai thông tin của người học trái quy định (Điều 5 khoản 4)."}, {"tinh_huong": "Cô Vân thấy em An bị mấy bạn đánh sau giờ ra chơi, nghĩ 'chuyện trẻ con' nên bỏ qua.", "ket_luan": "→ Vi phạm. Điều 5 khoản 4: phải báo cáo kịp thời với lãnh đạo, cơ quan có thẩm quyền; Điều 4 khoản 6 cấm thờ ơ, né tránh."}, {"tinh_huong": "Cô Lệ thông báo: em nào không đăng ký chương trình thiện nguyện cuối tuần (tự nguyện) sẽ bị trừ điểm rèn luyện.", "ket_luan": "→ Vi phạm. Điều 5 khoản 4 cấm ép buộc người học tham gia hoạt động mang tính chất tự nguyện."}, {"tinh_huong": "Thầy Khoa sửa tăng điểm kiểm tra của con người quen để em đủ điểm xét thi đua.", "ket_luan": "→ Vi phạm. Điều 5 khoản 4 cấm gian lận, cố ý làm sai lệch kết quả đánh giá; khoản 3 yêu cầu đánh giá đúng thực chất."}], "nho": ["Điều 5 khoản 4 = '5 KHÔNG': Phân biệt – Xúc phạm – Ép buộc – Công khai (thông tin) – Gian lận (nhớ: P-X-É-C-G).", "'Phát hiện bạo lực là PHẢI báo' – không có chữ 'có thể'.", "Ép buộc **người học** (Điều 5) tự nguyện; ép buộc **cha mẹ** là Điều 8 – phân biệt theo đối tượng bị ép."]}, {"id": "L7-3", "ten": "Thông tư 03/2026: ứng xử với đồng nghiệp và cán bộ quản lý (Điều 6, 7)", "tomtat": ["Điều 6 khoản 1: ứng xử với đồng nghiệp trung thực, chân thành, đoàn kết, hợp tác, chia sẻ trách nhiệm, giúp đỡ lẫn nhau; **tự phê bình và phê bình** khách quan, nghiêm túc, **thẳng thắn**, xây dựng.", "Điều 6 khoản 2: tôn trọng, lắng nghe ý kiến; phối hợp, trao đổi kinh nghiệm, học hỏi.", "Điều 6 khoản 3 (không được): **xúc phạm, chia rẽ, gây mất đoàn kết** nội bộ; **né tránh, đùn đẩy trách nhiệm**; **công khai thông tin của đồng nghiệp trái quy định**.", "Điều 7 khoản 1: **chấp hành** phân công, chỉ đạo, điều hành của cán bộ quản lý trong phạm vi chức năng, nhiệm vụ được giao.", "Điều 7 khoản 2: lắng nghe, **cầu thị** tiếp thu ý kiến đánh giá, góp ý.", "Điều 7 khoản 3: tích cực **tham mưu** và thể hiện rõ **chính kiến** theo chức năng, nhiệm vụ.", "Điều 7 khoản 4 (không được): **xúc phạm, gây mất đoàn kết** nội bộ; **thờ ơ, né tránh hoặc che giấu** hành vi sai phạm của cán bộ quản lý.", "Điều 4 khoản 6 cũng cấm thờ ơ, né tránh, che giấu vi phạm của người học, đồng nghiệp.", "Ứng xử trên mạng với đồng nghiệp, cán bộ quản lý vẫn phải tuân Điều 4 khoản 2 (có trách nhiệm khi ứng xử trên không gian mạng)."], "bay": ["⚠ Điều 6 (đồng nghiệp) ≠ Điều 7 (cán bộ quản lý): 'công khai thông tin trái quy định' và 'đùn đẩy trách nhiệm' chỉ thấy ở Điều 6 khoản 3.", "⚠ Điều 7 khoản 1: chấp hành chỉ đạo 'trong phạm vi chức năng, nhiệm vụ được giao'; khoản 3: 'thể hiện rõ chính kiến' (không im lặng, cũng không xúc phạm).", "⚠ 'Thờ ơ, né tránh hoặc che giấu' (Điều 7 K4) ≠ 'né tránh, đùn đẩy trách nhiệm' (Điều 6 K3).", "⚠ Phê bình đồng nghiệp: phải 'khách quan, nghiêm túc, thẳng thắn, xây dựng' (không phải né tránh va chạm)."], "cauhoi": [{"t": "s", "q": "Nhà giáo ứng xử với đồng nghiệp được quy định tại điều nào của Thông tư 03/2026/TT-BGDĐT?", "o": ["Điều 5", "Điều 6", "Điều 7", "Điều 8"], "a": [1], "e": "Điều 5: người học; Điều 6: đồng nghiệp; Điều 7: cán bộ quản lý; Điều 8: cha mẹ.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6"}, {"t": "s", "q": "Nhà giáo ứng xử với cán bộ quản lý cơ sở giáo dục được quy định tại điều nào của Thông tư 03/2026/TT-BGDĐT?", "o": ["Điều 6", "Điều 8", "Điều 9", "Điều 7"], "a": [3], "e": "Điều 7 quy định ứng xử với cán bộ quản lý cơ sở giáo dục.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7"}, {"t": "s", "q": "Theo Điều 6 khoản 1 Thông tư 03/2026/TT-BGDĐT, nhà giáo tự phê bình và phê bình đồng nghiệp như thế nào?", "o": ["Khách quan, nghiêm túc, thẳng thắn, xây dựng", "Tế nhị, né tránh va chạm, giữ hòa khí", "Kín đáo, chỉ trao đổi riêng, không ghi nhận", "Nghiêm khắc, quyết liệt, không cần xây dựng"], "a": [0], "e": "Khoản 1: khách quan, nghiêm túc, thẳng thắn, xây dựng.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6 khoản 1"}, {"t": "s", "q": "Phát biểu nào đúng về ứng xử của nhà giáo với đồng nghiệp theo Điều 6 Thông tư 03/2026/TT-BGDĐT?", "o": ["Không được phê bình đồng nghiệp dưới mọi hình thức", "Được đùn đẩy trách nhiệm nếu công việc ngoài chuyên môn", "Không được công khai thông tin của đồng nghiệp trái quy định", "Được công khai thông tin của đồng nghiệp nếu đã phổ biến trong trường"], "a": [2], "e": "Điều 6 khoản 1 khuyến khích phê bình xây dựng; khoản 3 cấm công khai thông tin trái quy định và đùn đẩy trách nhiệm.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6"}, {"t": "s", "q": "Điều 7 khoản 1 Thông tư 03/2026/TT-BGDĐT yêu cầu nhà giáo chấp hành phân công, chỉ đạo, điều hành của cán bộ quản lý trong phạm vi nào?", "o": ["Mọi nội dung chỉ đạo, không điều kiện", "Chỉ khi chỉ đạo bằng văn bản", "Chức năng, nhiệm vụ được giao", "Chỉ khi được hưởng thêm phụ cấp"], "a": [2], "e": "Khoản 1: chấp hành trong phạm vi chức năng, nhiệm vụ được giao.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7 khoản 1"}, {"t": "s", "q": "Theo Điều 7 khoản 3 Thông tư 03/2026/TT-BGDĐT, nhà giáo ứng xử với cán bộ quản lý như thế nào?", "o": ["Tích cực tham mưu và thể hiện rõ chính kiến theo chức năng, nhiệm vụ", "Không bày tỏ ý kiến trái chiều", "Chỉ tham mưu khi được yêu cầu bằng văn bản", "Thể hiện chính kiến bằng mọi hình thức, kể cả trên mạng xã hội"], "a": [0], "e": "Khoản 3: tích cực tham mưu và thể hiện rõ chính kiến theo chức năng, nhiệm vụ (đúng kênh, không xúc phạm).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7 khoản 3"}, {"t": "s", "q": "Giáo viên biết cán bộ quản lý có sai phạm nhưng im lặng cho yên chuyện. Hành vi này vi phạm quy định nào?", "o": ["Không vi phạm vì cán bộ quản lý ở cấp cao hơn", "Chỉ vi phạm nếu sai phạm liên quan tài chính", "Điều 6 khoản 3: không công khai thông tin của đồng nghiệp", "Điều 7 khoản 4: không thờ ơ, né tránh hoặc che giấu hành vi sai phạm của cán bộ quản lý"], "a": [3], "e": "Điều 7 khoản 4 cấm thờ ơ, né tránh, che giấu sai phạm của cán bộ quản lý, không giới hạn loại sai phạm.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7 khoản 4"}, {"t": "s", "q": "Hiệu trưởng đột xuất giao thêm việc trong phạm vi nhiệm vụ, một giáo viên phản ứng gay gắt trên nhóm Zalo của trường. Đánh giá nào đúng?", "o": ["Phù hợp vì đó là cách thể hiện chính kiến", "Không phù hợp: phải chấp hành phân công, nếu có ý kiến thì tham mưu đúng cách, không xúc phạm, không gây mất đoàn kết", "Phù hợp vì nhóm Zalo là nơi trao đổi nội bộ", "Không phù hợp chỉ vì chưa có văn bản giao việc"], "a": [1], "e": "Điều 7: chấp hành phân công (K1), tham mưu/thể hiện chính kiến theo chức năng (K3), không xúc phạm, gây mất đoàn kết (K4). Bẫy: 'chính kiến' không đồng nghĩa phản ứng gay gắt công khai.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7; Điều 4 khoản 2"}, {"t": "s", "q": "Thầy B đẩy hết phần việc nhóm cho đồng nghiệp để tránh trách nhiệm. Hành vi này vi phạm quy định nào?", "o": ["Điều 6 khoản 3: không né tránh, đùn đẩy trách nhiệm", "Điều 7 khoản 4: không thờ ơ với sai phạm của cán bộ quản lý", "Điều 5 khoản 4: không phân biệt đối xử người học", "Điều 9 khoản 4: không tham gia mê tín dị đoan"], "a": [0], "e": "Đùn đẩy trách nhiệm cho đồng nghiệp thuộc Điều 6 khoản 3.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6 khoản 3"}, {"t": "s", "q": "Nội dung nào chỉ có trong Điều 6 khoản 3 (đồng nghiệp) mà không có trong Điều 7 khoản 4 (cán bộ quản lý) của Thông tư 03/2026/TT-BGDĐT?", "o": ["Xúc phạm", "Gây mất đoàn kết nội bộ", "Công khai thông tin trái quy định", "Thờ ơ, né tránh hoặc che giấu hành vi sai phạm"], "a": [2], "e": "Điều 7 khoản 4 gồm xúc phạm, gây mất đoàn kết, thờ ơ/né tránh/che giấu sai phạm; 'công khai thông tin trái quy định' chỉ nằm ở Điều 6 khoản 3.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6 khoản 3; Điều 7 khoản 4"}, {"t": "s", "q": "Thầy C thấy đồng nghiệp tự ý sửa điểm cho học sinh nhưng im lặng 'để tránh va chạm, giữ đoàn kết'. Đánh giá nào đúng?", "o": ["Đúng, vì giữ đoàn kết là yêu cầu của Điều 6", "Sai, vì không được thờ ơ, né tránh hoặc che giấu vi phạm của đồng nghiệp (Điều 4 khoản 6)", "Đúng, vì việc đánh giá điểm là việc của người sửa", "Chỉ sai nếu học sinh phản ánh"], "a": [1], "e": "Điều 4 khoản 6 cấm né tránh, che giấu vi phạm của đồng nghiệp; sửa điểm là làm sai lệch kết quả đánh giá (Điều 5 khoản 4). Đoàn kết không có nghĩa là bao che.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6; Điều 5 khoản 4"}, {"t": "s", "q": "Theo Điều 7 khoản 2 Thông tư 03/2026/TT-BGDĐT, nhà giáo tiếp thu ý kiến đánh giá, góp ý của cán bộ quản lý với thái độ nào?", "o": ["Tiếp thu có chọn lọc, từ chối nếu không đồng ý", "Tiếp thu khi được cán bộ quản lý yêu cầu", "Ghi nhận nhưng không cần thay đổi", "Lắng nghe, cầu thị"], "a": [3], "e": "Khoản 2: lắng nghe, cầu thị tiếp thu ý kiến đánh giá, góp ý. (Cụm 'có chọn lọc' là về khoa học công nghệ ở Điều 4 khoản 2.)", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7 khoản 2"}, {"t": "m", "q": "Những hành vi nào nhà giáo không được làm với đồng nghiệp theo Điều 6 khoản 3 Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Chia rẽ, gây mất đoàn kết nội bộ", "Né tránh, đùn đẩy trách nhiệm", "Xúc phạm đồng nghiệp", "Trao đổi kinh nghiệm, học hỏi lẫn nhau", "Phê bình khách quan, thẳng thắn, xây dựng"], "a": [0, 1, 2], "e": "Phê bình xây dựng và trao đổi kinh nghiệm là nội dung được khuyến khích (khoản 1, 2).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6"}, {"t": "m", "q": "Theo Điều 7 Thông tư 03/2026/TT-BGDĐT, nhà giáo cần thực hiện những việc nào với cán bộ quản lý? (chọn tất cả đáp án đúng)", "o": ["Lắng nghe, cầu thị tiếp thu ý kiến góp ý", "Im lặng, không phản biện để giữ đoàn kết", "Tích cực tham mưu và thể hiện rõ chính kiến", "Che giấu sai phạm để bảo vệ uy tín tập thể", "Chấp hành phân công, chỉ đạo, điều hành trong phạm vi chức năng, nhiệm vụ"], "a": [0, 2, 4], "e": "Hai đáp án sai trái khoản 3 và khoản 4 Điều 7.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7"}, {"t": "m", "q": "Nhà giáo không thờ ơ, né tránh hoặc che giấu hành vi vi phạm của những ai theo Điều 4 khoản 6 và Điều 7 khoản 4 Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Người học", "Cha mẹ người học", "Khách đến cơ sở giáo dục", "Đồng nghiệp", "Cán bộ quản lý cơ sở giáo dục"], "a": [0, 3, 4], "e": "Điều 4 khoản 6: vi phạm của người học, đồng nghiệp; Điều 7 khoản 4: sai phạm của cán bộ quản lý. Cha mẹ, khách không nằm trong các quy định này.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6; Điều 7 khoản 4"}, {"t": "m", "q": "Hành vi nào sau đây vi phạm quy tắc ứng xử của nhà giáo theo Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Góp ý thẳng thắn, xây dựng về chuyên môn trong họp tổ", "Im lặng khi thấy đồng nghiệp sửa điểm cho học sinh", "Đề xuất phương án khác với kế hoạch của nhà trường trong cuộc họp hội đồng", "Đăng bài xúc phạm đồng nghiệp trong nhóm chat", "Đẩy việc của mình cho đồng nghiệp để né trách nhiệm"], "a": [1, 3, 4], "e": "Ba hành vi đầu vi phạm Điều 4 khoản 6, Điều 6 khoản 3; hai hành vi sau là phê bình xây dựng và tham mưu theo Điều 6 khoản 1, Điều 7 khoản 3.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4, 6, 7"}, {"t": "m", "q": "Điều 6 khoản 1 Thông tư 03/2026/TT-BGDĐT yêu cầu nhà giáo ứng xử với đồng nghiệp thế nào? (chọn tất cả đáp án đúng)", "o": ["Chia sẻ trách nhiệm, giúp đỡ lẫn nhau", "Chỉ giúp đỡ đồng nghiệp cùng tổ chuyên môn", "Tự phê bình và phê bình khách quan, nghiêm túc, thẳng thắn, xây dựng", "Trung thực, chân thành, đoàn kết, hợp tác", "Không phê bình để giữ hòa khí"], "a": [0, 2, 3], "e": "Khoản 1 không hạn chế đối tượng giúp đỡ và yêu cầu phê bình thẳng thắn, xây dựng.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6 khoản 1"}, {"t": "f", "q": "Nhà giáo tự phê bình và phê bình khách quan, nghiêm túc, ____, xây dựng.", "a": [["thẳng thắn"]], "e": "Điều 6 khoản 1.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6 khoản 1", "o": [["thẳng thắn"], ["gay gắt"], ["kín đáo"], ["nhẹ nhàng"]], "k": 0}, {"t": "f", "q": "Nhà giáo không xúc phạm, chia rẽ, gây mất ____ nội bộ.", "a": [["đoàn kết"]], "e": "Điều 6 khoản 3.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6 khoản 3", "o": [["uy tín"], ["trật tự"], ["đoàn kết"], ["hòa khí"]], "k": 2}, {"t": "f", "q": "Nhà giáo không né tránh, ____ trách nhiệm với đồng nghiệp.", "a": [["đùn đẩy"]], "e": "Điều 6 khoản 3.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6 khoản 3", "o": [["chia sẻ"], ["đùn đẩy"], ["tranh giành"], ["ủy thác"]], "k": 1}, {"t": "f", "q": "Nhà giáo ứng xử với cán bộ quản lý cơ sở giáo dục được quy định tại Điều ____ Thông tư 03/2026/TT-BGDĐT.", "a": [["7", "bảy"]], "e": "Điều 7.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7", "o": [["7"], ["6"], ["8"], ["9"]], "k": 0}, {"t": "f", "q": "Nhà giáo ứng xử với đồng nghiệp được quy định tại Điều ____ Thông tư 03/2026/TT-BGDĐT.", "a": [["6", "sáu"]], "e": "Điều 6.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 6", "o": [["5"], ["7"], ["6"], ["8"]], "k": 2}, {"t": "f", "q": "Nhà giáo chấp hành phân công, chỉ đạo, điều hành của cán bộ quản lý trong phạm vi ____, nhiệm vụ được giao.", "a": [["chức năng"]], "e": "Điều 7 khoản 1.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7 khoản 1", "o": [["quyền hạn"], ["chức năng"], ["năng lực"], ["sở trường"]], "k": 1}, {"t": "f", "q": "Nhà giáo lắng nghe, ____ tiếp thu ý kiến đánh giá, góp ý của cán bộ quản lý.", "a": [["cầu thị"]], "e": "Điều 7 khoản 2.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7 khoản 2", "o": [["có chọn lọc"], ["hình thức"], ["cầu thị"], ["thụ động"]], "k": 2}, {"t": "f", "q": "Nhà giáo tích cực ____ và thể hiện rõ chính kiến theo chức năng, nhiệm vụ.", "a": [["tham mưu"]], "e": "Điều 7 khoản 3.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 7 khoản 3", "o": [["phục tùng"], ["né tránh"], ["tham mưu"], ["chờ đợi"]], "k": 2}], "ynho": ["Điều **6** = đồng nghiệp; Điều **7** = cán bộ quản lý.", "Điều 6 khoản 3 cấm: **xúc phạm, chia rẽ**; **né tránh, đùn đẩy** trách nhiệm; **công khai thông tin** đồng nghiệp trái quy định.", "Điều 7 khoản 1: **chấp hành** chỉ đạo trong phạm vi **chức năng, nhiệm vụ** được giao.", "Điều 7 khoản 3: tích cực **tham mưu**, thể hiện rõ **chính kiến**.", "Điều 7 khoản 4 cấm: xúc phạm, mất đoàn kết; **thờ ơ, né tránh hoặc che giấu** sai phạm của cán bộ quản lý."], "bang": [{"tieu_de": "Điều 6 (đồng nghiệp) và Điều 7 (cán bộ quản lý)", "cot": ["Tiêu chí", "Điều 6", "Điều 7"], "dong": [["Số khoản", "3 khoản", "4 khoản"], ["Khoản 'không được'", "Khoản 3", "Khoản 4"], ["Xúc phạm, mất đoàn kết", "Có (xúc phạm, chia rẽ, gây mất đoàn kết)", "Có (xúc phạm, gây mất đoàn kết)"], ["Đùn đẩy trách nhiệm; công khai thông tin trái quy định", "Có", "Không có"], ["Thờ ơ, né tránh hoặc che giấu sai phạm", "Không (chỉ né tránh, đùn đẩy)", "Có"], ["Tham mưu, thể hiện chính kiến", "Không", "Có (khoản 3)"]]}], "vidu": [{"tinh_huong": "Trong họp hội đồng, cô Hạnh thấy lịch kiểm tra do phó hiệu trưởng xếp bị chồng chéo, đã trình bày ý kiến có dẫn chứng và đề xuất phương án.", "ket_luan": "→ Đúng. Điều 7 khoản 3: tham mưu và thể hiện rõ chính kiến theo chức năng, nhiệm vụ; không xúc phạm ai."}, {"tinh_huong": "Thầy Đức chụp màn hình hoàn cảnh gia đình riêng của cô Trang rồi gửi vào nhóm Zalo của các thầy cô trong trường.", "ket_luan": "→ Vi phạm. Điều 6 khoản 3 cấm công khai thông tin của đồng nghiệp trái quy định."}, {"tinh_huong": "Sau buổi họp phân công, cô Yến đăng Facebook những lời chê bai, xúc phạm hiệu trưởng.", "ket_luan": "→ Vi phạm. Điều 7 khoản 4 cấm xúc phạm, gây mất đoàn kết nội bộ; Điều 4 khoản 2 yêu cầu có trách nhiệm trên không gian mạng."}, {"tinh_huong": "Phần mềm nhập điểm bị sai do cô Quỳnh nhập nhầm, nhưng cô nói với tổ trưởng là lỗi của cô Ly.", "ket_luan": "→ Vi phạm. Điều 6 khoản 3 cấm né tránh, đùn đẩy trách nhiệm."}, {"tinh_huong": "Thầy Tín biết phó hiệu trưởng có sai phạm trong một khoản thu nhưng im lặng cho yên chuyện.", "ket_luan": "→ Vi phạm. Điều 7 khoản 4 cấm thờ ơ, né tránh hoặc che giấu hành vi sai phạm của cán bộ quản lý."}], "nho": ["Điều 6 'ba không': **X**úc phạm/chia rẽ – **Đ**ùn đẩy – **C**ông khai thông tin (X-Đ-C). Điều 7 không có 'đùn đẩy', 'công khai'.", "Điều 7: Chấp hành – Cầu thị – Tham mưu (K1-K2-K3), còn K4 là các điều cấm.", "Góp ý thì 'thẳng thắn, xây dựng', không 'xúc phạm' và cũng không 'im lặng né tránh'."]}, {"id": "L7-4", "ten": "Thông tư 03/2026: ứng xử với cha mẹ người học, cộng đồng và trên không gian mạng (Điều 8, 9)", "tomtat": ["Điều 8 khoản 1: sẵn sàng hợp tác, hỗ trợ, chia sẻ về hoạt động giảng dạy, giáo dục vì sự tiến bộ của người học.", "Điều 8 khoản 2: chủ động, kịp thời cung cấp, trao đổi thông tin **trung thực** về người học; chương trình, kế hoạch giảng dạy, giáo dục **khi được sự đồng ý của cấp quản lý theo thẩm quyền**.", "Điều 8 khoản 3: khuyến khích, tạo điều kiện để cha mẹ tham gia hoạt động giáo dục.", "Điều 8 khoản 4 (không được): **xúc phạm, áp đặt, vụ lợi, ép buộc** cha mẹ tham gia hoạt động **trái quy định của Nhà nước** và các hoạt động mang tính chất **tự nguyện**.", "Điều 9 khoản 1: chấp hành nội quy, quy tắc nơi công cộng; tôn trọng không gian chung; ứng xử văn minh, lịch thiệp; bảo vệ cảnh quan, môi trường.", "Điều 9 khoản 2: tự nguyện, tích cực hoạt động xã hội; bảo vệ môi trường; từ thiện, nhân đạo; xây dựng xã hội học tập, văn hóa đọc, khuyến học, khuyến tài.", "Điều 9 khoản 3: lan tỏa giá trị nhân văn, việc tốt; chủ động truyền thông về giáo dục, **chống tin giả** liên quan lĩnh vực giáo dục và nhà giáo trên **kênh mạng xã hội chính thống**; công khai, minh bạch thông tin khi tham gia hoạt động xã hội.", "Điều 9 khoản 4 (không được): tham gia, ủng hộ hoạt động **mê tín dị đoan** và hoạt động gây **chia rẽ khối đại đoàn kết toàn dân tộc**.", "Ứng xử trên không gian mạng thể hiện ở **Điều 4 khoản 2** (có trách nhiệm khi sử dụng thông tin và ứng xử trên không gian mạng) và **Điều 9 khoản 3** (chống tin giả, kênh mạng xã hội chính thống); không có điều riêng tên 'Ứng xử trên không gian mạng' trong nhóm Điều 4–9.", "Thông tin của người học: Điều 5 khoản 4 cấm công khai trái quy định; trao đổi với cha mẹ phải trung thực (Điều 8 khoản 2)."], "bay": ["⚠ Điều 8 khoản 4: cấm ép buộc cha mẹ tham gia hoạt động **trái quy định của Nhà nước** VÀ hoạt động **tự nguyện**; còn Điều 5 khoản 4 là ép buộc **người học** tham gia hoạt động tự nguyện.", "⚠ Điều 9 khoản 3: chống tin giả trên kênh mạng xã hội **chính thống** (không phải mọi kênh).", "⚠ Điều 8 khoản 2: thông tin về chương trình, kế hoạch giảng dạy cần **sự đồng ý của cấp quản lý theo thẩm quyền**; thông tin về người học phải **trung thực**.", "⚠ 'Mê tín dị đoan' ≠ lễ hội, tín ngưỡng thông thường; khoản 4 Điều 9 cấm 'tham gia, ủng hộ' hoạt động mê tín dị đoan."], "cauhoi": [{"t": "s", "q": "Theo Điều 8 khoản 2 Thông tư 03/2026/TT-BGDĐT, nhà giáo cung cấp thông tin về chương trình, kế hoạch giảng dạy, giáo dục khi nào?", "o": ["Khi cha mẹ người học có văn bản yêu cầu", "Khi được sự đồng ý của cấp quản lý theo thẩm quyền", "Khi được tổ trưởng chuyên môn đồng ý", "Bất cứ lúc nào, không cần điều kiện"], "a": [1], "e": "Khoản 2: chương trình, kế hoạch giảng dạy, giáo dục chỉ cung cấp khi được sự đồng ý của cấp quản lý theo thẩm quyền.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8 khoản 2"}, {"t": "s", "q": "Phát biểu nào đúng về các hành vi nhà giáo không được làm với cha mẹ người học theo Điều 8 khoản 4 Thông tư 03/2026/TT-BGDĐT?", "o": ["Không xúc phạm, hách dịch, vụ lợi, ép buộc cha mẹ", "Không xúc phạm, áp đặt, gây phiền hà, ép buộc cha mẹ", "Không phân biệt đối xử, áp đặt, vụ lợi, ép buộc cha mẹ", "Không xúc phạm, áp đặt, vụ lợi, ép buộc cha mẹ"], "a": [3], "e": "Điều 8 khoản 4: xúc phạm, áp đặt, vụ lợi, ép buộc. 'Hách dịch', 'gây phiền hà' là cách nói của TT06/2019 (cán bộ quản lý).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8 khoản 4"}, {"t": "s", "q": "Điều 8 khoản 3 Thông tư 03/2026/TT-BGDĐT yêu cầu nhà giáo đối với việc tham gia hoạt động giáo dục của cha mẹ người học như thế nào?", "o": ["Khuyến khích, tạo điều kiện", "Bắt buộc cha mẹ tham gia mọi hoạt động", "Chỉ mời khi cần đóng góp", "Chỉ thông báo, không cần tạo điều kiện"], "a": [0], "e": "Khoản 3: khuyến khích, tạo điều kiện để cha mẹ tham gia hoạt động giáo dục.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8 khoản 3"}, {"t": "s", "q": "Điều 9 khoản 3 Thông tư 03/2026/TT-BGDĐT yêu cầu nhà giáo chống tin giả trên kênh nào?", "o": ["Mọi nền tảng mạng xã hội", "Kênh mạng xã hội cá nhân của nhà giáo", "Kênh mạng xã hội chính thống", "Kênh thông tin của cơ quan báo chí"], "a": [2], "e": "Khoản 3: chủ động truyền thông, chống tin giả liên quan lĩnh vực giáo dục và nhà giáo trên kênh mạng xã hội chính thống.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9 khoản 3"}, {"t": "s", "q": "Điều 9 khoản 4 Thông tư 03/2026/TT-BGDĐT cấm nhà giáo tham gia, ủng hộ hoạt động nào?", "o": ["Lễ hội truyền thống và hoạt động tôn giáo", "Từ thiện, nhân đạo và hoạt động khuyến học", "Mê tín dị đoan và hoạt động gây chia rẽ khối đại đoàn kết toàn dân tộc", "Hoạt động xã hội do tổ chức không chính thống tổ chức"], "a": [2], "e": "Khoản 4: mê tín dị đoan và hoạt động gây chia rẽ khối đại đoàn kết toàn dân tộc. Lễ hội truyền thống không bị cấm.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9 khoản 4"}, {"t": "s", "q": "Trong các Điều 4–9 Thông tư 03/2026/TT-BGDĐT, nội dung về ứng xử trên không gian mạng nằm ở đâu?", "o": ["Điều 4 khoản 2 và Điều 9 khoản 3", "Điều 5 khoản 3 và Điều 9 khoản 1", "Điều 6 khoản 1 và Điều 8 khoản 2", "Điều 7 khoản 3 và Điều 9 khoản 4"], "a": [0], "e": "Điều 4 khoản 2 (trách nhiệm khi sử dụng thông tin, ứng xử trên không gian mạng) và Điều 9 khoản 3 (chống tin giả, kênh mạng xã hội chính thống).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 2; Điều 9 khoản 3"}, {"t": "s", "q": "Phụ huynh nhắn tin xin điểm số và nhận xét chi tiết về cả các bạn khác trong lớp. Cách ứng xử nào của giáo viên phù hợp với Thông tư 03/2026/TT-BGDĐT?", "o": ["Gửi bảng điểm cả lớp để phụ huynh tham khảo", "Từ chối mọi trao đổi với phụ huynh", "Nhận xét tùy ý, nhẹ nhàng cho phụ huynh yên tâm", "Trao đổi thông tin trung thực về chính học sinh của phụ huynh, không công khai thông tin học sinh khác trái quy định"], "a": [3], "e": "Điều 8 khoản 2: thông tin về người học phải trung thực; Điều 5 khoản 4: không công khai thông tin người học trái quy định.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8 khoản 2; Điều 5 khoản 4"}, {"t": "s", "q": "Giáo viên mời phụ huynh cho con học thêm tại nhà mình và ngầm ám chỉ học sinh không học sẽ bị đánh giá thấp. Hành vi nào sau đây KHÔNG thuộc các quy định bị vi phạm theo Thông tư 03/2026/TT-BGDĐT?", "o": ["Lợi dụng chức danh nhà giáo để tư lợi (Điều 4 khoản 6)", "Tham gia hoạt động mê tín dị đoan (Điều 9 khoản 4)", "Ép buộc, vụ lợi đối với cha mẹ (Điều 8 khoản 4)", "Đánh giá không đúng thực chất, trù dập người học (Điều 5)"], "a": [1], "e": "Hành vi trên liên quan tư lợi, ép buộc/vụ lợi với cha mẹ, trù dập/đánh giá sai thực chất; không liên quan mê tín dị đoan.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6; Điều 5; Điều 8 khoản 4"}, {"t": "s", "q": "Giáo viên nhận xét học lực của học sinh sai sự thật để cha mẹ yên tâm. Hành vi này vi phạm yêu cầu nào?", "o": ["Thông tin trao đổi với cha mẹ phải trung thực (Điều 8 khoản 2)", "Thông tin phải được cấp quản lý đồng ý trước khi trao đổi", "Không được trao đổi bằng tin nhắn", "Chỉ được trao đổi tại nhà trường"], "a": [0], "e": "Điều 8 khoản 2 yêu cầu thông tin về người học phải trung thực.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8 khoản 2"}, {"t": "s", "q": "Khi vận động từ thiện hoặc tham gia hoạt động xã hội, nhà giáo phải thực hiện yêu cầu nào theo Điều 9 khoản 3 Thông tư 03/2026/TT-BGDĐT?", "o": ["Giữ kín thông tin để tránh phô trương", "Chỉ công khai khi có yêu cầu của cơ quan", "Công khai, minh bạch thông tin", "Công khai trong nhóm bạn bè"], "a": [2], "e": "Khoản 3: công khai, minh bạch thông tin khi tham gia hoạt động xã hội.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9 khoản 3"}, {"t": "s", "q": "Giáo viên chia sẻ tin chưa kiểm chứng về nhà trường lên mạng xã hội cá nhân. Hành vi này trái với yêu cầu nào của Thông tư 03/2026/TT-BGDĐT?", "o": ["Tự nguyện tham gia hoạt động xã hội (Điều 9 khoản 2)", "Có trách nhiệm khi sử dụng thông tin và ứng xử trên không gian mạng (Điều 4 khoản 2)", "Chấp hành nội quy nơi công cộng (Điều 9 khoản 1)", "Chấp hành phân công của người có thẩm quyền (Điều 4 khoản 1)"], "a": [1], "e": "Điều 4 khoản 2 yêu cầu có trách nhiệm khi sử dụng thông tin và ứng xử trên không gian mạng; Điều 9 khoản 3 còn yêu cầu chống tin giả.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 2; Điều 9 khoản 3"}, {"t": "s", "q": "Nội dung 'xây dựng xã hội học tập, văn hóa đọc, khuyến học, khuyến tài' thuộc điều khoản nào của Thông tư 03/2026/TT-BGDĐT?", "o": ["Điều 9 khoản 1", "Điều 8 khoản 3", "Điều 4 khoản 4", "Điều 9 khoản 2"], "a": [3], "e": "Điều 9 khoản 2 (hoạt động xã hội, từ thiện, nhân đạo, xã hội học tập, văn hóa đọc, khuyến học, khuyến tài).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9 khoản 2"}, {"t": "m", "q": "Những hành vi nào nhà giáo không được làm với cha mẹ người học theo Điều 8 khoản 4 Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Khuyến khích cha mẹ tham gia hoạt động giáo dục", "Sẵn sàng hợp tác, chia sẻ với cha mẹ", "Áp đặt cha mẹ người học", "Ép buộc cha mẹ tham gia hoạt động mang tính chất tự nguyện", "Xúc phạm cha mẹ người học"], "a": [2, 3, 4], "e": "Hai phương án sau là việc nhà giáo cần làm (khoản 1, 3).", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8"}, {"t": "m", "q": "Hành vi mời học thêm tại nhà, ngầm ám chỉ học sinh không học sẽ bị đánh giá thấp, vi phạm những quy định nào của Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Trù dập, đánh giá không đúng thực chất người học (Điều 5)", "Gây mất đoàn kết với cán bộ quản lý (Điều 7 khoản 4)", "Lợi dụng chức danh nhà giáo để tư lợi (Điều 4 khoản 6)", "Ép buộc, vụ lợi đối với cha mẹ (Điều 8 khoản 4)", "Ủng hộ hoạt động mê tín dị đoan (Điều 9 khoản 4)"], "a": [0, 2, 3], "e": "Hành vi liên quan tư lợi, vụ lợi/ép buộc cha mẹ và trù dập người học.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 4, 5, 8"}, {"t": "m", "q": "Điều 9 khoản 3 Thông tư 03/2026/TT-BGDĐT quy định nhà giáo thực hiện những việc nào? (chọn tất cả đáp án đúng)", "o": ["Chia sẻ mọi thông tin trên mạng để tăng tương tác", "Lan tỏa giá trị nhân văn, việc tốt", "Chủ động truyền thông về giáo dục", "Chỉ truyền thông trên kênh mạng xã hội cá nhân", "Chống tin giả liên quan lĩnh vực giáo dục và nhà giáo"], "a": [1, 2, 4], "e": "Khoản 3 nhấn mạnh kênh mạng xã hội chính thống, chống tin giả, không chia sẻ tùy tiện.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9 khoản 3"}, {"t": "m", "q": "Điều 9 khoản 2 Thông tư 03/2026/TT-BGDĐT khuyến khích nhà giáo tham gia những hoạt động nào? (chọn tất cả đáp án đúng)", "o": ["Hoạt động xã hội một cách tự nguyện, tích cực", "Hoạt động gây chia rẽ khối đại đoàn kết toàn dân tộc", "Hoạt động mê tín dị đoan", "Hoạt động từ thiện, nhân đạo", "Khuyến học, khuyến tài"], "a": [0, 3, 4], "e": "Hai phương án sau bị cấm bởi khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9 khoản 2, 4"}, {"t": "m", "q": "Khi giáo viên trao đổi với phụ huynh, cách ứng xử nào đúng theo Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Trao đổi thông tin trung thực về học sinh", "Cung cấp chương trình, kế hoạch giảng dạy khi được cấp quản lý đồng ý theo thẩm quyền", "Gửi bảng điểm cả lớp vào nhóm phụ huynh", "Từ chối mọi trao đổi với cha mẹ", "Không công khai thông tin học sinh khác trái quy định"], "a": [0, 1, 4], "e": "Ba phương án đầu phù hợp Điều 8 khoản 2 và Điều 5 khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8 khoản 2; Điều 5 khoản 4"}, {"t": "f", "q": "Nhà giáo ứng xử với cha mẹ hoặc người giám hộ của người học được quy định tại Điều ____ Thông tư 03/2026/TT-BGDĐT.", "a": [["8", "tám"]], "e": "Điều 8.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8", "o": [["8"], ["7"], ["9"], ["10"]], "k": 0}, {"t": "f", "q": "Nhà giáo ứng xử với cộng đồng được quy định tại Điều ____ Thông tư 03/2026/TT-BGDĐT.", "a": [["9", "chín"]], "e": "Điều 9.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9", "o": [["8"], ["9"], ["10"], ["7"]], "k": 1}, {"t": "f", "q": "Nhà giáo không xúc phạm, áp đặt, ____, ép buộc cha mẹ tham gia hoạt động trái quy định của Nhà nước và hoạt động mang tính chất tự nguyện.", "a": [["vụ lợi"]], "e": "Điều 8 khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8 khoản 4", "o": [["khuyến khích"], ["gợi ý"], ["thuyết phục"], ["vụ lợi"]], "k": 3}, {"t": "f", "q": "Nhà giáo cung cấp, trao đổi thông tin ____ về người học.", "a": [["trung thực"]], "e": "Điều 8 khoản 2.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8 khoản 2", "o": [["chủ quan"], ["trung thực"], ["một chiều"], ["bí mật"]], "k": 1}, {"t": "f", "q": "Nhà giáo cung cấp chương trình, kế hoạch giảng dạy khi được sự đồng ý của cấp ____ theo thẩm quyền.", "a": [["quản lý"]], "e": "Điều 8 khoản 2.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 8 khoản 2", "o": [["quản lý"], ["trên"], ["địa phương"], ["cao nhất"]], "k": 0}, {"t": "f", "q": "Nhà giáo chủ động truyền thông về giáo dục, chống ____ liên quan lĩnh vực giáo dục và nhà giáo trên kênh mạng xã hội chính thống.", "a": [["tin giả"]], "e": "Điều 9 khoản 3.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9 khoản 3", "o": [["tin giả"], ["tin vui"], ["quảng cáo"], ["tin đồn"]], "k": 0}, {"t": "f", "q": "Nhà giáo không tham gia, ủng hộ hoạt động ____ dị đoan.", "a": [["mê tín"]], "e": "Điều 9 khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9 khoản 4", "o": [["mê tín"], ["mê muội"], ["tín ngưỡng"], ["mê hoặc"]], "k": 0}, {"t": "f", "q": "Nhà giáo không tham gia, ủng hộ hoạt động gây chia rẽ khối đại ____ toàn dân tộc.", "a": [["đoàn kết"]], "e": "Điều 9 khoản 4.", "r": "Thông tư 03/2026/TT-BGDĐT Điều 9 khoản 4", "o": [["hòa hợp"], ["thống nhất"], ["hòa giải"], ["đoàn kết"]], "k": 3}], "ynho": ["Điều **8** = cha mẹ/người giám hộ; Điều **9** = cộng đồng.", "Thông tin về người học phải **trung thực**; chương trình, kế hoạch giảng dạy cần **sự đồng ý của cấp quản lý**.", "Điều 8 khoản 4 cấm **xúc phạm, áp đặt, vụ lợi, ép buộc** cha mẹ.", "Điều 9 khoản 3: **chống tin giả** trên kênh mạng xã hội **chính thống**.", "Điều 9 khoản 4 cấm tham gia, ủng hộ **mê tín dị đoan** và hoạt động **chia rẽ** khối đại đoàn kết toàn dân tộc."], "bang": [{"tieu_de": "Điều 8 và Điều 9", "cot": ["Điều/khoản", "Nội dung", "Từ khoá"], "dong": [["8 K1", "Hợp tác, hỗ trợ, chia sẻ với cha mẹ", "Vì sự tiến bộ của người học"], ["8 K2", "Cung cấp, trao đổi thông tin", "Trung thực; kế hoạch giảng dạy cần cấp quản lý đồng ý"], ["8 K3", "Tạo điều kiện cha mẹ tham gia", "Hoạt động giáo dục"], ["8 K4", "Không được làm", "Xúc phạm, áp đặt, vụ lợi, ép buộc"], ["9 K1-2", "Nơi công cộng; hoạt động xã hội", "Văn minh, từ thiện, khuyến học"], ["9 K3", "Truyền thông, mạng xã hội", "Chống tin giả; kênh chính thống"], ["9 K4", "Không được làm", "Mê tín dị đoan; chia rẽ"]]}, {"tieu_de": "Ứng xử trên không gian mạng nằm rải rác ở đâu", "cot": ["Điều", "Nội dung"], "dong": [["Điều 4 khoản 2", "Có trách nhiệm khi sử dụng thông tin và ứng xử trên không gian mạng"], ["Điều 9 khoản 3", "Chống tin giả, kênh mạng xã hội chính thống"], ["Điều 5 khoản 4", "Không công khai thông tin người học trái quy định"], ["Điều 6 khoản 3", "Không công khai thông tin đồng nghiệp trái quy định"], ["Điều 8 khoản 2", "Thông tin cho cha mẹ phải trung thực"]]}], "vidu": [{"tinh_huong": "Cô Mai nhắn riêng cho phụ huynh em Bình, nêu đúng thực tế học lực của em và đề xuất cách phối hợp hỗ trợ.", "ket_luan": "→ Đúng. Điều 8 khoản 2: chủ động, kịp thời trao đổi thông tin trung thực về người học."}, {"tinh_huong": "Thầy Quân nhắn vào nhóm Zalo lớp: phụ huynh nào không tham gia buổi quyên góp tự nguyện thì cháu sẽ bị nhắc tên.", "ket_luan": "→ Vi phạm. Điều 8 khoản 4 cấm ép buộc cha mẹ tham gia hoạt động mang tính chất tự nguyện."}, {"tinh_huong": "Cô Hoa giới thiệu phụ huynh mua sản phẩm của người quen để nhận hoa hồng.", "ket_luan": "→ Vi phạm. Điều 8 khoản 4 cấm vụ lợi đối với cha mẹ; Điều 4 khoản 6 cấm tư lợi."}, {"tinh_huong": "Thầy Đạt thấy tin giả về lịch thi lan trên mạng nên đăng bài đính chính, dẫn thông báo của cơ quan giáo dục trên kênh chính thống.", "ket_luan": "→ Đúng. Điều 9 khoản 3: chủ động truyền thông, chống tin giả trên kênh mạng xã hội chính thống."}, {"tinh_huong": "Phụ huynh xin bản kế hoạch dạy học cả năm của trường; thầy Long xin ý kiến lãnh đạo nhà trường trước khi gửi.", "ket_luan": "→ Đúng. Điều 8 khoản 2: cung cấp chương trình, kế hoạch giảng dạy khi được sự đồng ý của cấp quản lý theo thẩm quyền."}], "nho": ["Điều 8 khoản 4 = 'X-A-V-É': **X**úc phạm – **Á**p đặt – **V**ụ lợi – **É**p buộc (cha mẹ).", "Chống tin giả = 'kênh chính thống' (không phải mọi kênh).", "Thông tin: về **người học** thì 'trung thực'; về **kế hoạch, chương trình** thì 'cấp quản lý đồng ý'.", "Không có 'Điều ứng xử không gian mạng' riêng: nhớ ba chỗ chính Điều 4 K2, Điều 9 K3, Điều 5-6 (công khai thông tin)."]}, {"id": "L7-5", "ten": "Thông tư 06/2019: phạm vi, mục đích, nguyên tắc và ứng xử chung (Điều 1–4, 14)", "tomtat": ["TT 06/2019/TT-BGDĐT ký **12/4/2019**, hiệu lực **28/5/2019** (Điều 14 khoản 1); gồm **3 chương, 14 điều**.", "Phạm vi: quy tắc ứng xử trong cơ sở giáo dục **mầm non, phổ thông, thường xuyên**; áp dụng với cán bộ quản lý, giáo viên, nhân viên, **người học, cha mẹ người học**.", "Điều 6 (ứng xử của giáo viên) **hết hiệu lực từ 30/01/2026** do TT 03/2026 thay thế; các điều còn lại vẫn là văn bản gốc.", "Điều 2 (mục đích): ứng xử theo chuẩn mực đạo đức, thuần phong mỹ tục; ngăn ngừa, xử lý kịp thời hành vi tiêu cực, thiếu tính giáo dục; xây dựng văn hóa học đường, môi trường an toàn, lành mạnh, thân thiện, phòng chống bạo lực học đường.", "Điều 3 khoản 2: thể hiện **5 giá trị cốt lõi**: **nhân ái, tôn trọng, trách nhiệm, hợp tác, trung thực**.", "Điều 3 khoản 5: xây dựng, sửa đổi Bộ Quy tắc phải thảo luận dân chủ, khách quan, công khai và được **đồng thuận của đa số thành viên**.", "Điều 4 (ứng xử chung) có **9 khoản**: K1 thực hiện quy định pháp luật về quyền, nghĩa vụ; K2 lối sống lành mạnh, tích cực; K3 bảo vệ cảnh quan, môi trường xanh, sạch, đẹp.", "Điều 4 khoản 4 (trang phục): cán bộ quản lý, giáo viên **lịch sự, phù hợp**; nhân viên **phù hợp tính chất công việc**; người học **sạch sẽ, gọn gàng**; cha mẹ và khách phù hợp môi trường giáo dục. Khoản 5: không trang phục gây phản cảm.", "Điều 4 khoản 6: không hút thuốc, sử dụng đồ uống có cồn, chất cấm **trong cơ sở giáo dục**; không tham gia tệ nạn xã hội.", "Điều 4 khoản 7: không dùng **mạng xã hội** để phát tán, tuyên truyền, bình luận thông tin, hình ảnh trái thuần phong mỹ tục, trái đường lối, chính sách, pháp luật hoặc ảnh hưởng xấu môi trường giáo dục.", "Điều 4 khoản 8: không gian lận, dối trá, vu khống, gây hiềm khích, quấy rối, ép buộc, đe dọa, bạo lực với người khác; khoản 9: không làm tổn hại sức khỏe, danh dự, nhân phẩm của bản thân, người khác và uy tín tập thể."], "bay": ["⚠ TT06: cấm hút thuốc, rượu bia, chất cấm **'trong cơ sở giáo dục'** ≠ TT03: **'khi thực hiện nhiệm vụ'**.", "⚠ 5 giá trị cốt lõi: nhân ái, tôn trọng, trách nhiệm, hợp tác, **trung thực** (không có 'kỷ luật', 'sáng tạo', 'đoàn kết').", "⚠ Xây dựng Bộ Quy tắc: 'đồng thuận của **đa số** thành viên' (không phải toàn thể, không phải hiệu trưởng tự quyết).", "⚠ Hiệu lực 28/5/2019 (≠ ngày ký 12/4/2019, ≠ ngày đăng Công báo 03/5/2019); chỉ **Điều 6** hết hiệu lực từ 30/01/2026."], "cauhoi": [{"t": "s", "q": "Thông tư 06/2019/TT-BGDĐT có hiệu lực thi hành từ ngày nào?", "o": ["12/4/2019", "28/5/2019", "03/5/2019", "30/01/2026"], "a": [1], "e": "Điều 14 khoản 1: hiệu lực 28/5/2019. 12/4/2019 là ngày ký; 03/5/2019 là ngày đăng Công báo; 30/01/2026 là ngày Điều 6 hết hiệu lực.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 14 khoản 1"}, {"t": "s", "q": "Thông tư 06/2019/TT-BGDĐT gồm bao nhiêu chương, bao nhiêu điều?", "o": ["3 chương, 15 điều", "2 chương, 14 điều", "4 chương, 14 điều", "3 chương, 14 điều"], "a": [3], "e": "TT06/2019 gồm 3 chương, 14 điều (TT03/2026 là 3 chương, 15 điều).", "r": "Thông tư 06/2019/TT-BGDĐT"}, {"t": "s", "q": "Thông tư 06/2019/TT-BGDĐT quy định quy tắc ứng xử trong loại cơ sở giáo dục nào?", "o": ["Mầm non, phổ thông, thường xuyên", "Mầm non, phổ thông, đại học", "Chỉ phổ thông", "Phổ thông, thường xuyên, nghề nghiệp"], "a": [0], "e": "Điều 1: cơ sở giáo dục mầm non, phổ thông, thường xuyên.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 1"}, {"t": "s", "q": "Đối tượng áp dụng của Thông tư 06/2019/TT-BGDĐT là ai?", "o": ["Chỉ cán bộ quản lý và giáo viên", "Giáo viên, người học và cơ quan quản lý giáo dục các cấp", "Cán bộ quản lý, giáo viên, nhân viên, người học và cha mẹ người học", "Cán bộ quản lý, giáo viên, nhân viên và học viên đại học"], "a": [2], "e": "Điều 1: gồm cả người học, cha mẹ người học (khác TT03/2026 chỉ dành cho nhà giáo).", "r": "Thông tư 06/2019/TT-BGDĐT Điều 1"}, {"t": "s", "q": "Năm giá trị cốt lõi cần thể hiện trong Bộ Quy tắc ứng xử theo Thông tư 06/2019/TT-BGDĐT là gì?", "o": ["Nhân ái, tôn trọng, kỷ luật, hợp tác, trung thực", "Nhân ái, đoàn kết, trách nhiệm, hợp tác, trung thực", "Nhân ái, tôn trọng, trách nhiệm, hợp tác, trung thực", "Nhân ái, tôn trọng, trách nhiệm, sáng tạo, trung thực"], "a": [2], "e": "Điều 3 khoản 2: nhân ái, tôn trọng, trách nhiệm, hợp tác, trung thực. Các đáp án nhiễu đổi 1 giá trị.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 3 khoản 2"}, {"t": "s", "q": "Việc xây dựng, sửa đổi Bộ Quy tắc ứng xử của cơ sở giáo dục phải được thực hiện thế nào theo Thông tư 06/2019/TT-BGDĐT?", "o": ["Thảo luận dân chủ, khách quan, công khai và được đồng thuận của đa số thành viên", "Do thủ trưởng quyết định sau khi lấy ý kiến", "Được toàn thể thành viên đồng thuận 100%", "Do sở giáo dục và đào tạo phê duyệt"], "a": [0], "e": "Điều 3 khoản 5: đồng thuận của đa số thành viên.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 3 khoản 5"}, {"t": "s", "q": "Theo Thông tư 06/2019/TT-BGDĐT (Điều 4 khoản 6), cấm hút thuốc, sử dụng đồ uống có cồn, chất cấm ở đâu?", "o": ["Khi thực hiện nhiệm vụ", "Trong giờ lên lớp", "Ở mọi nơi, mọi lúc", "Trong cơ sở giáo dục"], "a": [3], "e": "TT06: 'trong cơ sở giáo dục'. Cụm 'khi thực hiện nhiệm vụ' là của TT03/2026.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4 khoản 6"}, {"t": "s", "q": "Quy tắc ứng xử chung trong Thông tư 06/2019/TT-BGDĐT (Điều 4) gồm bao nhiêu khoản?", "o": ["6 khoản", "9 khoản", "8 khoản", "10 khoản"], "a": [1], "e": "Điều 4 gồm 9 khoản.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4"}, {"t": "s", "q": "Phát biểu nào đúng về quy định mạng xã hội tại Điều 4 khoản 7 Thông tư 06/2019/TT-BGDĐT?", "o": ["Không dùng mạng xã hội để phát tán, tuyên truyền, bình luận thông tin, hình ảnh trái thuần phong mỹ tục, trái đường lối, chính sách, pháp luật hoặc ảnh hưởng xấu môi trường giáo dục", "Không được sử dụng mạng xã hội trong cơ sở giáo dục dưới mọi hình thức", "Chỉ cấm đăng thông tin trái pháp luật, không cấm hình ảnh", "Chỉ áp dụng với giáo viên, không áp dụng với người học"], "a": [0], "e": "Điều 4 khoản 7 cấm dùng mạng xã hội để phát tán... thông tin, hình ảnh trái thuần phong mỹ tục, đường lối, chính sách, pháp luật, hoặc ảnh hưởng xấu; không cấm sử dụng mạng xã hội nói chung và áp dụng với mọi đối tượng.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4 khoản 7"}, {"t": "s", "q": "Theo Điều 4 khoản 4 Thông tư 06/2019/TT-BGDĐT, yêu cầu trang phục nào đúng?", "o": ["Giáo viên: phù hợp tính chất công việc; người học: lịch sự", "Nhân viên: lịch sự, phù hợp; người học: phù hợp tính chất công việc", "Cán bộ quản lý, giáo viên: lịch sự, phù hợp; người học: sạch sẽ, gọn gàng", "Cha mẹ và khách: sạch sẽ, gọn gàng; người học: lịch sự"], "a": [2], "e": "Khoản 4: CBQL, giáo viên lịch sự, phù hợp; nhân viên phù hợp tính chất công việc; người học sạch sẽ, gọn gàng; cha mẹ, khách phù hợp môi trường giáo dục.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4 khoản 4"}, {"t": "s", "q": "Điều nào của Thông tư 06/2019/TT-BGDĐT đã hết hiệu lực từ 30/01/2026 do Thông tư 03/2026/TT-BGDĐT thay thế?", "o": ["Điều 5", "Điều 6", "Điều 8", "Toàn bộ Thông tư"], "a": [1], "e": "Chỉ Điều 6 (ứng xử của giáo viên) hết hiệu lực; Điều 5 (cán bộ quản lý), Điều 8 (người học)... vẫn còn.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 6; Thông tư 03/2026/TT-BGDĐT"}, {"t": "s", "q": "Mục đích của Thông tư 06/2019/TT-BGDĐT bao gồm nội dung nào sau đây?", "o": ["Quy định mức xử phạt vi phạm hành chính trong cơ sở giáo dục", "Chỉ điều chỉnh ứng xử của giáo viên", "Thay thế Điều lệ trường phổ thông", "Ngăn ngừa, xử lý kịp thời hành vi tiêu cực, thiếu tính giáo dục"], "a": [3], "e": "Điều 2: điều chỉnh cách ứng xử theo chuẩn mực; ngăn ngừa, xử lý kịp thời hành vi tiêu cực, thiếu tính giáo dục; xây dựng văn hóa học đường.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 2"}, {"t": "m", "q": "Những giá trị nào thuộc 5 giá trị cốt lõi theo Điều 3 khoản 2 Thông tư 06/2019/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Nhân ái", "Sáng tạo", "Hợp tác", "Đoàn kết", "Trung thực"], "a": [0, 2, 4], "e": "5 giá trị: nhân ái, tôn trọng, trách nhiệm, hợp tác, trung thực. 'Sáng tạo', 'đoàn kết' không có.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 3 khoản 2"}, {"t": "m", "q": "Điều 4 khoản 8 Thông tư 06/2019/TT-BGDĐT cấm những hành vi nào đối với người khác? (chọn tất cả đáp án đúng)", "o": ["Phê bình xây dựng", "Gian lận, dối trá", "Vu khống, gây hiềm khích", "Quan tâm, chia sẻ, giúp đỡ", "Quấy rối, đe dọa, bạo lực"], "a": [1, 2, 4], "e": "Khoản 8: không gian lận, dối trá, vu khống, gây hiềm khích, quấy rối, ép buộc, đe dọa, bạo lực. Quan tâm, chia sẻ là khoản 2.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4 khoản 8"}, {"t": "m", "q": "Phát biểu nào đúng về Điều 4 Thông tư 06/2019/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Khoản 6 chỉ cấm hút thuốc khi thực hiện nhiệm vụ", "Khoản 9 cấm làm tổn hại sức khỏe, danh dự, nhân phẩm của bản thân, người khác và uy tín tập thể", "Khoản 5 cấm sử dụng trang phục gây phản cảm", "Khoản 6 cấm hút thuốc, đồ uống có cồn, chất cấm trong cơ sở giáo dục", "Khoản 4 yêu cầu mọi đối tượng mặc đồng phục thống nhất"], "a": [1, 2, 3], "e": "Khoản 6 dùng cụm 'trong cơ sở giáo dục'; khoản 4 quy định yêu cầu trang phục khác nhau theo đối tượng.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4"}, {"t": "m", "q": "Những đối tượng nào thuộc phạm vi áp dụng của Thông tư 06/2019/TT-BGDĐT (Điều 1)? (chọn tất cả đáp án đúng)", "o": ["Cán bộ quản lý", "Người học và cha mẹ người học", "Học viên cơ sở giáo dục đại học", "Cán bộ quản lý giáo dục cấp tỉnh", "Giáo viên và nhân viên"], "a": [0, 1, 4], "e": "Đối tượng: cán bộ quản lý, giáo viên, nhân viên, người học, cha mẹ người học trong cơ sở giáo dục mầm non, phổ thông, thường xuyên.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 1"}, {"t": "m", "q": "Những nội dung nào thuộc nguyên tắc xây dựng Bộ Quy tắc ứng xử theo Thông tư 06/2019/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Thảo luận dân chủ, khách quan, công khai", "Do thủ trưởng tự quyết định, không cần lấy ý kiến", "Dễ hiểu, dễ thực hiện, phù hợp lứa tuổi, cấp học, vùng miền", "Tuân thủ pháp luật", "Áp dụng giống nhau cho mọi cấp học"], "a": [0, 2, 3], "e": "Điều 3: tuân thủ pháp luật; dễ hiểu, dễ thực hiện, phù hợp lứa tuổi, cấp học, vùng miền; thảo luận dân chủ, khách quan, công khai.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 3"}, {"t": "f", "q": "Thông tư 06/2019/TT-BGDĐT có hiệu lực từ ngày ____.", "a": [["28/5/2019", "28/05/2019"]], "e": "Điều 14 khoản 1.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 14 khoản 1", "o": [["28/5/2018"], ["15/5/2019"], ["28/5/2019"], ["30/1/2026"]], "k": 2}, {"t": "f", "q": "Thông tư 06/2019/TT-BGDĐT gồm ____ chương và ____ điều.", "a": [["3", "03", "ba"], ["14", "mười bốn"]], "e": "3 chương, 14 điều.", "r": "Thông tư 06/2019/TT-BGDĐT", "o": [["3", "14"], ["3", "15"], ["2", "14"], ["4", "13"]], "k": 0}, {"t": "f", "q": "Năm giá trị cốt lõi: nhân ái, tôn trọng, trách nhiệm, hợp tác, ____.", "a": [["trung thực"]], "e": "Điều 3 khoản 2.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 3 khoản 2", "o": [["sáng tạo"], ["đoàn kết"], ["kỷ luật"], ["trung thực"]], "k": 3}, {"t": "f", "q": "Thông tư 06/2019/TT-BGDĐT cấm hút thuốc, sử dụng đồ uống có cồn, chất cấm ____ cơ sở giáo dục.", "a": [["trong"]], "e": "Điều 4 khoản 6: 'trong cơ sở giáo dục'.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4 khoản 6", "o": [["ngoài"], ["gần"], ["trong"], ["xung quanh"]], "k": 2}, {"t": "f", "q": "Xây dựng, sửa đổi Bộ Quy tắc phải được đồng thuận của đa số ____.", "a": [["thành viên"]], "e": "Điều 3 khoản 5.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 3 khoản 5", "o": [["thành viên"], ["học sinh"], ["giáo viên"], ["cán bộ quản lý"]], "k": 0}, {"t": "f", "q": "Điều 4 khoản 7 cấm dùng ____ để phát tán, tuyên truyền, bình luận thông tin, hình ảnh trái thuần phong mỹ tục.", "a": [["mạng xã hội"]], "e": "Điều 4 khoản 7.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4 khoản 7", "o": [["báo chí"], ["tin nhắn"], ["mạng xã hội"], ["điện thoại"]], "k": 2}, {"t": "f", "q": "Quy tắc ứng xử chung của Thông tư 06/2019/TT-BGDĐT được quy định tại Điều ____.", "a": [["4", "bốn"]], "e": "Điều 4.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4", "o": [["3"], ["5"], ["6"], ["4"]], "k": 3}, {"t": "f", "q": "Điều ____ của Thông tư 06/2019/TT-BGDĐT (ứng xử của giáo viên) hết hiệu lực từ 30/01/2026.", "a": [["6", "sáu"]], "e": "Điều 6 bị thay thế bởi TT03/2026.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 6", "o": [["6"], ["5"], ["7"], ["8"]], "k": 0}, {"t": "f", "q": "Thông tư 06/2019/TT-BGDĐT nhằm ngăn ngừa, xử lý kịp thời hành vi tiêu cực, thiếu tính ____.", "a": [["giáo dục"]], "e": "Điều 2.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 2", "o": [["khoa học"], ["pháp lý"], ["kỷ luật"], ["giáo dục"]], "k": 3}], "ynho": ["TT **06/2019**: ký **12/4/2019**, hiệu lực **28/5/2019**; **3 chương, 14 điều**.", "**Điều 6** hết hiệu lực từ **30/01/2026** (do TT03/2026 thay thế).", "**5 giá trị cốt lõi**: nhân ái, tôn trọng, trách nhiệm, hợp tác, trung thực.", "Điều 4 có **9 khoản**; cấm hút thuốc, cồn, chất cấm **trong cơ sở giáo dục**.", "Xây dựng, sửa đổi Bộ Quy tắc cần **đồng thuận của đa số** thành viên."], "bang": [{"tieu_de": "Điều 4 TT06/2019 (9 khoản)", "cot": ["Khoản", "Nội dung"], "dong": [["1", "Thực hiện quy định pháp luật về quyền, nghĩa vụ"], ["2", "Lối sống lành mạnh, tích cực"], ["3", "Bảo vệ cảnh quan, môi trường xanh, sạch, đẹp"], ["4-5", "Trang phục phù hợp (K4); không trang phục phản cảm (K5)"], ["6", "Không hút thuốc, đồ uống có cồn, chất cấm trong cơ sở giáo dục; không tệ nạn xã hội"], ["7", "Không dùng mạng xã hội phát tán thông tin, hình ảnh trái thuần phong mỹ tục, pháp luật"], ["8", "Không gian lận, dối trá, vu khống, quấy rối, ép buộc, đe dọa, bạo lực"], ["9", "Không làm tổn hại sức khỏe, danh dự, nhân phẩm; uy tín tập thể"]]}, {"tieu_de": "Mốc và con số của TT06/2019", "cot": ["Nội dung", "Con số"], "dong": [["Ngày ký", "12/4/2019"], ["Hiệu lực (Điều 14 khoản 1)", "28/5/2019"], ["Công báo (không phải hiệu lực)", "03/5/2019"], ["Quy mô", "3 chương, 14 điều"], ["Điều hết hiệu lực", "Điều 6, từ 30/01/2026"], ["Giá trị cốt lõi", "5 (nhân ái, tôn trọng, trách nhiệm, hợp tác, trung thực)"]]}], "vidu": [{"tinh_huong": "Thầy Dũng mặc áo ba lỗ, quần đùi đứng lớp dạy Tin học.", "ket_luan": "→ Không đúng. Điều 4 TT06 khoản 4 yêu cầu giáo viên trang phục lịch sự, phù hợp; khoản 5 cấm trang phục gây phản cảm."}, {"tinh_huong": "Thầy Kiên đăng Facebook kèm hình ảnh trái thuần phong mỹ tục và bình luận về một học sinh của trường.", "ket_luan": "→ Vi phạm. Điều 4 khoản 7 cấm dùng mạng xã hội phát tán, bình luận thông tin, hình ảnh trái thuần phong mỹ tục."}, {"tinh_huong": "Thầy Phong hút thuốc trong phòng bộ môn sau khi học sinh đã ra về.", "ket_luan": "→ Vi phạm theo TT06. Điều 4 khoản 6 cấm hút thuốc trong cơ sở giáo dục (phạm vi rộng hơn 'khi thực hiện nhiệm vụ' của TT03)."}, {"tinh_huong": "Hiệu trưởng tự ký ban hành Bộ Quy tắc của trường mà không tổ chức thảo luận, lấy ý kiến thành viên.", "ket_luan": "→ Chưa đúng. Điều 3 khoản 5: phải thảo luận dân chủ, khách quan, công khai và được đồng thuận của đa số thành viên."}, {"tinh_huong": "Cô Nga hỏi: Điều 6 TT06/2019 về ứng xử của giáo viên còn hiệu lực không?", "ket_luan": "→ Không. Điều 6 hết hiệu lực từ 30/01/2026, đã được TT03/2026 thay thế; các điều khác vẫn còn là văn bản gốc."}], "nho": ["5 giá trị cốt lõi: **N-T-T-H-T** = Nhân ái – Tôn trọng – Trách nhiệm – Hợp tác – Trung thực.", "Mốc ngày: ký **12/4** → Công báo 03/5 → hiệu lực **28/5/2019** (mốc cần nhớ là 28/5).", "TT06 'trong cơ sở' ≠ TT03 'khi thực hiện nhiệm vụ'.", "Bộ Quy tắc: 'đa số', không phải 'toàn thể', không phải hiệu trưởng tự quyết."]}, {"id": "L7-6", "ten": "Thông tư 06/2019: ứng xử của cán bộ quản lý, nhân viên, người học, cha mẹ, khách; tổ chức thực hiện; so sánh với TT03/2026", "tomtat": ["Điều 5 (cán bộ quản lý): K1 với **người học**; K2 với **giáo viên, nhân viên**; K3 với **cha mẹ người học**; K4 với **khách** đến cơ sở giáo dục.", "Điều 5 khoản 1: không xúc phạm, ép buộc, trù dập, bạo hành người học. Khoản 2: không **hách dịch**, gây khó khăn, xúc phạm, định kiến, **thiên vị**, vụ lợi, né tránh trách nhiệm hoặc che giấu vi phạm, đổ lỗi.", "Điều 5 khoản 3: với cha mẹ không xúc phạm, gây khó khăn, phiền hà, vụ lợi; khoản 4: với khách không xúc phạm, gây khó khăn, phiền hà.", "Điều 7 (nhân viên): ứng xử với người học, cán bộ quản lý và giáo viên, đồng nghiệp, cha mẹ và khách; không gây khó khăn, phiền hà, xúc phạm, bạo lực; không né tránh trách nhiệm, gây mất đoàn kết, vụ lợi.", "Điều 8 (**người học** phổ thông, GDTX): K1 với CBQL, giáo viên, nhân viên: kính trọng, lễ phép, trung thực; không bịa đặt thông tin, không xúc phạm. K2 với bạn: không nói tục, chửi bậy, miệt thị, xúc phạm; không bịa đặt, lôi kéo; không phát tán thông tin nói xấu bạn.", "Điều 9 (**cha mẹ người học**): K1 với người học; K2 với CBQL, giáo viên, nhân viên: tôn trọng, trách nhiệm, hợp tác, chia sẻ; **không bịa đặt thông tin; không xúc phạm** tinh thần, danh dự, nhân phẩm.", "Điều 10 (**khách**): với người học đúng mực, tôn trọng, thân thiện; với CBQL, giáo viên, nhân viên đúng mực, tôn trọng, không bịa đặt thông tin, không xúc phạm.", "Điều 11: **Vụ Giáo dục Chính trị và Công tác HSSV** hướng dẫn, kiểm tra. Điều 12: **sở GDĐT, phòng GDĐT** chỉ đạo, kiểm tra, giám sát việc xây dựng và thực hiện Bộ Quy tắc.", "Điều 13: thủ trưởng cơ sở giáo dục quy định cụ thể Bộ Quy tắc; công khai trên **website hoặc niêm yết bảng tin**, tuyên truyền; tổ chức thực hiện, đánh giá, tổng kết, báo cáo cấp quản lý trực tiếp **định kỳ mỗi năm học**; khen thưởng, kỷ luật.", "Điều 14: hiệu lực 28/5/2019; bãi bỏ quy định trước đây của Bộ trái với Thông tư.", "So sánh: chỉ **TT06** có quy tắc cho người học (Đ8), cha mẹ (Đ9), khách (Đ10); **TT03/2026** chỉ dành cho nhà giáo (có thêm chống tin giả, ứng xử không gian mạng, cấm gian lận đánh giá người học)."], "bay": ["⚠ Điều 8 = **người học**; Điều 9 = **cha mẹ**; Điều 10 = **khách** (trong TT06). Còn TT03/2026: Điều 8 = cha mẹ nhà giáo ứng xử; Điều 9 = cộng đồng.", "⚠ Báo cáo cấp quản lý trực tiếp **định kỳ mỗi năm học** (không phải mỗi học kỳ, mỗi quý).", "⚠ Công khai Bộ Quy tắc: trên website **hoặc** niêm yết bảng tin ('hoặc', không phải 'và').", "⚠ 'Hách dịch', 'phiền hà' là từ của TT06 (cán bộ quản lý); 'áp đặt', 'vụ lợi, ép buộc cha mẹ' là của TT03 Điều 8."], "cauhoi": [{"t": "s", "q": "Ứng xử của người học theo Thông tư 06/2019/TT-BGDĐT được quy định tại điều nào?", "o": ["Điều 7", "Điều 8", "Điều 9", "Điều 10"], "a": [1], "e": "Điều 7: nhân viên; Điều 8: người học; Điều 9: cha mẹ người học; Điều 10: khách.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 8"}, {"t": "s", "q": "Ứng xử của cha mẹ người học theo Thông tư 06/2019/TT-BGDĐT được quy định tại điều nào?", "o": ["Điều 8", "Điều 10", "Điều 5", "Điều 9"], "a": [3], "e": "Điều 9 quy định ứng xử của cha mẹ người học; Điều 10 là khách.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 9"}, {"t": "s", "q": "Hành vi nào cán bộ quản lý không được làm với giáo viên, nhân viên theo Điều 5 khoản 2 Thông tư 06/2019/TT-BGDĐT?", "o": ["Thiên vị", "Đồng hành cùng giáo viên, nhân viên", "Bảo vệ uy tín, danh dự, nhân phẩm của giáo viên", "Khích lệ giáo viên, nhân viên"], "a": [0], "e": "Khoản 2 cấm hách dịch, gây khó khăn, xúc phạm, định kiến, thiên vị, vụ lợi, né tránh trách nhiệm, che giấu vi phạm, đổ lỗi; các phương án còn lại là việc được yêu cầu.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 5 khoản 2"}, {"t": "s", "q": "Điều 5 Thông tư 06/2019/TT-BGDĐT quy định cán bộ quản lý ứng xử với những đối tượng nào?", "o": ["Người học; giáo viên; cha mẹ người học; cơ quan quản lý cấp trên", "Người học; giáo viên, nhân viên; cộng đồng; khách", "Người học; giáo viên, nhân viên; cha mẹ người học; khách đến cơ sở giáo dục", "Giáo viên, nhân viên; cha mẹ người học; khách; cán bộ quản lý khác"], "a": [2], "e": "Điều 5 có 4 khoản: người học, giáo viên và nhân viên, cha mẹ người học, khách.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 5"}, {"t": "s", "q": "Học sinh lớp 8 đăng ảnh chế giễu một bạn lên Facebook của lớp. Hành vi này vi phạm quy định nào của Thông tư 06/2019/TT-BGDĐT?", "o": ["Không vi phạm vì TT06 chỉ điều chỉnh ứng xử trong giờ học", "Điều 9 khoản 2: không bịa đặt thông tin với giáo viên", "Điều 8 khoản 2: không phát tán thông tin nói xấu, xúc phạm bạn", "Điều 8 khoản 3: kính trọng, lễ phép với cha mẹ"], "a": [2], "e": "Điều 8 khoản 2 (ứng xử với bạn): không nói tục, miệt thị, xúc phạm, bịa đặt, phát tán thông tin nói xấu; cùng với Điều 4 khoản 7, 8.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 8 khoản 2; Điều 4 khoản 7, 8"}, {"t": "s", "q": "Phụ huynh vào lớp, lớn tiếng xúc phạm cô giáo vì con bị phê bình. Hành vi này vi phạm quy định nào của Thông tư 06/2019/TT-BGDĐT?", "o": ["Điều 9 khoản 2: không bịa đặt thông tin, không xúc phạm tinh thần, danh dự, nhân phẩm của giáo viên", "Điều 9 khoản 1: không xúc phạm người học", "Điều 8 khoản 2: không nói tục, miệt thị bạn", "Điều 5 khoản 3: không gây phiền hà cha mẹ"], "a": [0], "e": "Điều 9 khoản 2 áp dụng cho cha mẹ với CBQL, giáo viên, nhân viên.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 9 khoản 2"}, {"t": "s", "q": "Theo Điều 13 Thông tư 06/2019/TT-BGDĐT, thủ trưởng cơ sở giáo dục báo cáo cấp quản lý trực tiếp việc thực hiện Bộ Quy tắc vào thời điểm nào?", "o": ["Định kỳ mỗi học kỳ", "Định kỳ mỗi quý", "Hằng tháng", "Định kỳ mỗi năm học"], "a": [3], "e": "Điều 13 khoản 3: tổ chức thực hiện, đánh giá, tổng kết, báo cáo cấp quản lý trực tiếp định kỳ mỗi năm học.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 13 khoản 3"}, {"t": "s", "q": "Theo Điều 13 Thông tư 06/2019/TT-BGDĐT, Bộ Quy tắc ứng xử của cơ sở giáo dục được công khai bằng hình thức nào?", "o": ["Trên website và niêm yết tại bảng tin, cả hai đều bắt buộc", "Trên website hoặc niêm yết tại bảng tin", "Chỉ gửi văn bản đến cha mẹ người học", "Chỉ phổ biến trong hội nghị cán bộ, viên chức"], "a": [1], "e": "Điều 13 khoản 2: công khai trên website 'hoặc' niêm yết bảng tin, kèm tuyên truyền. Bẫy: 'và', 'chỉ'.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 13 khoản 2"}, {"t": "s", "q": "Cơ quan nào hướng dẫn, kiểm tra việc thực hiện Thông tư 06/2019/TT-BGDĐT theo Điều 11?", "o": ["Vụ Giáo dục Chính trị và Công tác học sinh, sinh viên", "Vụ Giáo dục Trung học", "Cục Nhà giáo và Cán bộ quản lý cơ sở giáo dục", "Thanh tra Bộ Giáo dục và Đào tạo"], "a": [0], "e": "Điều 11: Vụ Giáo dục Chính trị và Công tác HSSV hướng dẫn, kiểm tra.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 11"}, {"t": "s", "q": "Theo Điều 12 Thông tư 06/2019/TT-BGDĐT, ai chỉ đạo, kiểm tra, giám sát việc xây dựng và thực hiện Bộ Quy tắc ứng xử?", "o": ["Ủy ban nhân dân cấp xã", "Hiệu trưởng các trường", "Sở giáo dục và đào tạo, phòng giáo dục và đào tạo", "Bộ trưởng Bộ Giáo dục và Đào tạo"], "a": [2], "e": "Điều 12: sở GDĐT, phòng GDĐT. (UBND xã, phường được giao trách nhiệm trong Thông tư 03/2026, không phải ở đây.)", "r": "Thông tư 06/2019/TT-BGDĐT Điều 12"}, {"t": "s", "q": "Phát biểu nào đúng khi so sánh Thông tư 03/2026/TT-BGDĐT và Thông tư 06/2019/TT-BGDĐT?", "o": ["TT06 cấm 'khi thực hiện nhiệm vụ'; TT03 cấm 'trong cơ sở giáo dục'", "TT06 cấm hút thuốc, đồ uống có cồn 'trong cơ sở giáo dục'; TT03 cấm 'khi thực hiện nhiệm vụ'", "Cả hai đều cấm 'ở mọi nơi, mọi lúc'", "TT03 cấm cả hút thuốc và rượu bia, còn TT06 chỉ cấm hút thuốc"], "a": [1], "e": "Đúng nguyên văn: TT06 Điều 4 khoản 6 'trong cơ sở giáo dục'; TT03 Điều 4 khoản 6 'khi thực hiện nhiệm vụ'.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 4 khoản 6; Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 6"}, {"t": "s", "q": "Quy tắc ứng xử của người học, cha mẹ người học và khách đến cơ sở giáo dục được quy định ở văn bản nào?", "o": ["Thông tư 03/2026/TT-BGDĐT", "Cả hai Thông tư đều quy định như nhau", "Quyết định 16/2008/QĐ-BGDĐT", "Thông tư 06/2019/TT-BGDĐT"], "a": [3], "e": "Chỉ TT06/2019 (Điều 8, 9, 10) có; TT03/2026 chỉ dành cho nhà giáo; QĐ 16/2008 (đạo đức nhà giáo) đã bị TT03 thay thế.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 8–10"}, {"t": "m", "q": "Hành vi nào người học không được làm với bạn học theo Điều 8 khoản 2 Thông tư 06/2019/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Phát tán thông tin nói xấu bạn", "Nói tục, chửi bậy", "Giúp đỡ bạn học", "Bịa đặt, lôi kéo bạn", "Tôn trọng sự khác biệt của bạn"], "a": [0, 1, 3], "e": "Hai phương án sau là yêu cầu tích cực (thân thiện, giúp đỡ, tôn trọng khác biệt).", "r": "Thông tư 06/2019/TT-BGDĐT Điều 8 khoản 2"}, {"t": "m", "q": "Hành vi nào cán bộ quản lý không được làm với người học theo Điều 5 khoản 1 Thông tư 06/2019/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Ép buộc", "Yêu thương, bao dung", "Lắng nghe, động viên", "Xúc phạm", "Bạo hành"], "a": [0, 3, 4], "e": "Khoản 1: không xúc phạm, ép buộc, trù dập, bạo hành; yêu thương, bao dung, lắng nghe, động viên là yêu cầu.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 5 khoản 1"}, {"t": "m", "q": "Trách nhiệm của thủ trưởng cơ sở giáo dục theo Điều 13 Thông tư 06/2019/TT-BGDĐT gồm những việc nào? (chọn tất cả đáp án đúng)", "o": ["Ban hành thông tư hướng dẫn", "Phê duyệt Bộ Quy tắc của các trường khác", "Công khai Bộ Quy tắc trên website hoặc niêm yết bảng tin, tuyên truyền", "Quy định cụ thể Bộ Quy tắc", "Khen thưởng, kỷ luật"], "a": [2, 3, 4], "e": "Điều 13 gồm quy định cụ thể, công khai/tuyên truyền, tổ chức thực hiện/báo cáo, khen thưởng/kỷ luật.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 13"}, {"t": "m", "q": "Những nội dung nào chỉ có trong Thông tư 06/2019/TT-BGDĐT mà không có trong Thông tư 03/2026/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Quy tắc ứng xử của cha mẹ người học", "Chống tin giả trên kênh mạng xã hội chính thống", "Ứng xử với cộng đồng (chống mê tín dị đoan)", "Quy tắc ứng xử của người học", "Quy tắc ứng xử của khách đến cơ sở giáo dục"], "a": [0, 3, 4], "e": "TT06 có Điều 8, 9, 10; còn chống tin giả và ứng xử với cộng đồng là nội dung của TT03/2026 (Điều 9).", "r": "Thông tư 06/2019/TT-BGDĐT Điều 8–10"}, {"t": "m", "q": "Cha mẹ người học không được làm gì với cán bộ quản lý, giáo viên, nhân viên theo Điều 9 khoản 2 Thông tư 06/2019/TT-BGDĐT? (chọn tất cả đáp án đúng)", "o": ["Hợp tác, chia sẻ", "Xúc phạm danh dự, nhân phẩm", "Bịa đặt thông tin", "Xúc phạm tinh thần", "Thể hiện trách nhiệm, tôn trọng"], "a": [1, 2, 3], "e": "Khoản 2: không bịa đặt thông tin; không xúc phạm tinh thần, danh dự, nhân phẩm.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 9 khoản 2"}, {"t": "f", "q": "Ứng xử của người học theo Thông tư 06/2019/TT-BGDĐT được quy định tại Điều ____.", "a": [["8", "tám"]], "e": "Điều 8.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 8", "o": [["7"], ["8"], ["9"], ["10"]], "k": 1}, {"t": "f", "q": "Ứng xử của cha mẹ người học theo Thông tư 06/2019/TT-BGDĐT được quy định tại Điều ____.", "a": [["9", "chín"]], "e": "Điều 9.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 9", "o": [["9"], ["8"], ["10"], ["11"]], "k": 0}, {"t": "f", "q": "Ứng xử của khách đến cơ sở giáo dục theo Thông tư 06/2019/TT-BGDĐT được quy định tại Điều ____.", "a": [["10", "mười"]], "e": "Điều 10.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 10", "o": [["9"], ["10"], ["11"], ["12"]], "k": 1}, {"t": "f", "q": "Thủ trưởng cơ sở giáo dục báo cáo cấp quản lý trực tiếp định kỳ mỗi ____.", "a": [["năm học"]], "e": "Điều 13 khoản 3.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 13 khoản 3", "o": [["tháng"], ["năm học"], ["học kỳ"], ["quý"]], "k": 1}, {"t": "f", "q": "Bộ Quy tắc ứng xử được công khai trên website hoặc ____ tại bảng tin.", "a": [["niêm yết"]], "e": "Điều 13 khoản 2.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 13 khoản 2", "o": [["đăng tải"], ["phát hành"], ["lưu hành"], ["niêm yết"]], "k": 3}, {"t": "f", "q": "Điều 14 bãi bỏ quy định trước đây của Bộ ____ với Thông tư này.", "a": [["trái"]], "e": "Điều 14.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 14", "o": [["phù hợp"], ["tương tự"], ["trái"], ["đúng"]], "k": 2}, {"t": "f", "q": "Cán bộ quản lý không hách dịch, gây khó khăn, xúc phạm, định kiến, ____, vụ lợi với giáo viên, nhân viên.", "a": [["thiên vị"]], "e": "Điều 5 khoản 2.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 5 khoản 2", "o": [["nể nang"], ["thiên vị"], ["ưu ái"], ["khoan dung"]], "k": 1}, {"t": "f", "q": "Người học không nói tục, chửi bậy, ____, xúc phạm bạn học.", "a": [["miệt thị"]], "e": "Điều 8 khoản 2.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 8 khoản 2", "o": [["khích lệ"], ["miệt thị"], ["tâng bốc"], ["khen ngợi"]], "k": 1}, {"t": "f", "q": "Cha mẹ người học không bịa đặt thông tin; không xúc phạm tinh thần, danh dự, ____ của giáo viên.", "a": [["nhân phẩm"]], "e": "Điều 9 khoản 2.", "r": "Thông tư 06/2019/TT-BGDĐT Điều 9 khoản 2", "o": [["tài sản"], ["tiền lương"], ["địa vị"], ["nhân phẩm"]], "k": 3}], "ynho": ["TT06: Điều **5** CBQL, **7** nhân viên, **8** người học, **9** cha mẹ, **10** khách.", "Điều 11: **Vụ Giáo dục Chính trị và Công tác HSSV**; Điều 12: **sở, phòng GDĐT**; Điều 13: **thủ trưởng** cơ sở giáo dục.", "Công khai Bộ Quy tắc trên **website hoặc** niêm yết bảng tin.", "Báo cáo cấp quản lý trực tiếp **định kỳ mỗi năm học**.", "Chỉ **TT06** có quy tắc cho người học, cha mẹ, khách; TT03/2026 chỉ dành cho nhà giáo."], "bang": [{"tieu_de": "Các điều của TT06/2019 cần nhớ", "cot": ["Điều", "Nội dung", "Từ khoá"], "dong": [["5", "Cán bộ quản lý", "K1 người học; K2 GV-NV (hách dịch, thiên vị); K3 cha mẹ; K4 khách"], ["7", "Nhân viên", "Không né tránh trách nhiệm, vụ lợi"], ["8", "Người học", "Lễ phép; không bịa đặt, nói tục, phát tán thông tin nói xấu bạn"], ["9", "Cha mẹ người học", "Không bịa đặt thông tin, không xúc phạm"], ["10", "Khách", "Đúng mực, tôn trọng, không bịa đặt"], ["11", "Hướng dẫn, kiểm tra", "Vụ Giáo dục Chính trị và Công tác HSSV"], ["12", "Chỉ đạo, kiểm tra, giám sát", "Sở GDĐT, phòng GDĐT"], ["13", "Tổ chức thực hiện", "Công khai; báo cáo mỗi năm học"]]}, {"tieu_de": "So sánh TT06/2019 với TT03/2026", "cot": ["Tiêu chí", "TT06/2019", "TT03/2026"], "dong": [["Đối tượng", "Cả cộng đồng trường học", "Chỉ nhà giáo"], ["Quy tắc cho người học, cha mẹ, khách", "Có (Điều 8, 9, 10)", "Không"], ["Điều về cha mẹ", "Điều 9: cha mẹ ứng xử", "Điều 8: nhà giáo ứng xử với cha mẹ"], ["Chống tin giả, không gian mạng", "Điều 4 khoản 7 (mạng xã hội)", "Điều 4 khoản 2; Điều 9 khoản 3"], ["Từ ngữ đặc trưng", "Hách dịch, phiền hà", "Áp đặt, vụ lợi, ép buộc"]]}], "vidu": [{"tinh_huong": "Phó hiệu trưởng ông Tâm hách dịch, thiên vị giáo viên thân với mình khi xếp lịch dạy.", "ket_luan": "→ Vi phạm. Điều 5 khoản 2 TT06 cấm cán bộ quản lý hách dịch, thiên vị, vụ lợi với giáo viên, nhân viên."}, {"tinh_huong": "Phụ huynh anh Hùng đăng vào nhóm Zalo lớp thông tin bịa đặt về cô chủ nhiệm.", "ket_luan": "→ Vi phạm. Điều 9 TT06: cha mẹ không bịa đặt thông tin, không xúc phạm giáo viên."}, {"tinh_huong": "Em Phát lập nhóm chat nói xấu bạn cùng lớp và phát tán tin nhắn bịa đặt.", "ket_luan": "→ Vi phạm. Điều 8 khoản 2 TT06: người học không bịa đặt, không phát tán thông tin nói xấu bạn."}, {"tinh_huong": "Một khách đến liên hệ công việc quát mắng, xúc phạm bác bảo vệ cổng trường.", "ket_luan": "→ Vi phạm. Điều 10 TT06: khách ứng xử đúng mực, tôn trọng, không xúc phạm cán bộ, giáo viên, nhân viên."}, {"tinh_huong": "Trường đăng Bộ Quy tắc trên website, mỗi năm học báo cáo cấp quản lý trực tiếp và có đánh giá, tổng kết.", "ket_luan": "→ Đúng. Điều 13 TT06: công khai trên website hoặc niêm yết bảng tin; báo cáo định kỳ mỗi năm học."}], "nho": ["Dãy 5-7-8-9-10 = Quản lý – Nhân viên – **H**ọc sinh – **P**hụ huynh – **K**hách; Điều 6 (giáo viên) đã mất hiệu lực.", "Điều 11-12-13 = Vụ → Sở/Phòng → Trường (từ trên xuống dưới).", "'**Hoặc**' website 'hoặc' bảng tin; báo cáo '**mỗi năm học**' (không phải học kỳ).", "Đảo số: TT06 Điều 8 = người học, TT03 Điều 8 = cha mẹ – cẩn thận khi làm đề."]}]});